@font-face{font-family:'Chakra Petch';src:url('../assets/fonts/chakra-600.ttf') format('truetype');font-weight:600;font-style:normal;font-display:swap}
@font-face{font-family:'Chakra Petch';src:url('../assets/fonts/chakra-700.ttf') format('truetype');font-weight:700;font-style:normal;font-display:swap}
