  ship.position.set(3230, 0.3, 1000); ship.rotation.y = -0.4; scene.add(ship);
  world.addAnimated((dt, t) => { ship.rotation.z = Math.sin(t * .35) * .014; ship.position.y = .3 + Math.sin(t * .4) * .3; });
}

