  // desert mesas
  for (const [x, z, r, h] of [[1520, 1950, 48, 55], [1880, 2620, 62, 72], [2420, 2140, 38, 42], [2730, 2600, 55, 62], [1180, 2500, 32, 36], [1700, 2850, 46, 50]]) {
