    const pos = geo.attributes.position;
    for (let i = 0; i < pos.count; i++) {
      const yy = pos.getY(i);
      if (yy > -h / 2 + 1) {
        pos.setX(i, pos.getX(i) + Math.sin(i * 4.7 + x) * r * .07);
        pos.setZ(i, pos.getZ(i) + Math.cos(i * 2.3 + z) * r * .07);
