259:   async _buildTerrain(progress) {
260:     const seg = SEGMENTS;
261:     const stride = seg + 1;
262:     for (let j = 0; j <= seg; j++) {
263:       const z = -HALF + (j / seg) * WORLD_SIZE;
264:       for (let i = 0; i <= seg; i++) {
265:         const x = -HALF + (i / seg) * WORLD_SIZE;
266:         let h = this.baseHeight(x, z);
267:         const near = this.roads.nearest(x, z, 62);
268:         if (near) {
269:           const corridor = near.road.width / 2 + 20;
270:           if (near.dist < corridor) {
271:             const bridge = near.seg?.bridge || (near.road.bridge && near.road.bridge);
272:             if (!(bridge && near.dist > near.road.width / 2 + 2)) {
273:               const t = 1 - smoothstep(near.road.width / 2 + 1.5, corridor, near.dist);
274:               h = lerp(h, near.y - 0.12, t * 0.94);
275:             }
276:           }
277:         }
278:         this.heightGrid[j * stride + i] = h;
279:       }
280:       if (j % 30 === 0) await progress(13 + (j / seg) * 30, 'Sculpting terrain and coastline');
281:     }
282:     this._buildTerrainMesh();
283:   }
