285:   terrainHeight(x, z) {
286:     const seg = SEGMENTS;
287:     const gx = clamp(((x + HALF) / WORLD_SIZE) * seg, 0, seg - 0.0001);
288:     const gz = clamp(((z + HALF) / WORLD_SIZE) * seg, 0, seg - 0.0001);
289:     const x0 = Math.floor(gx), z0 = Math.floor(gz);
290:     const tx = gx - x0, tz = gz - z0;
291:     const s = seg + 1;
292:     const h00 = this.heightGrid[z0 * s + x0], h10 = this.heightGrid[z0 * s + x0 + 1];
293:     const h01 = this.heightGrid[(z0 + 1) * s + x0], h11 = this.heightGrid[(z0 + 1) * s + x0 + 1];
294:     return lerp(lerp(h00, h10, tx), lerp(h01, h11, tx), tz);
295:   }
296: 
297:   surfaceAt(x, z) {
298:     const r = this.roads.surfaceAt(x, z);
299:     if (r) return { y: r.y + 0.12, onRoad: true, type: r.road.type, road: r.road, grip: r.road.type === 'dirt' ? 0.72 : 1 };
300:     const y = this.terrainHeight(x, z);
301:     const lake = dist2(x, z, 600, -1500) < 310;
302:     const sea = y < 0.4 && (x > 2450 || (x > 2250 && Math.abs(z - 1290) < 160));
303:     return { y: y + 0.03, onRoad: false, type: 'terrain', grip: 0.86, water: sea || (lake && y < 13), lake };
304:   }
