306:   heightAt(x, z) { return this.surfaceAt(x, z).y; }
307: 
308:   slopeAt(x, z) {
309:     const h = 2;
310:     const dx = this.heightAt(x + h, z) - this.heightAt(x - h, z);
311:     const dz = this.heightAt(x, z + h) - this.heightAt(x, z - h);
312:     return Math.hypot(dx, dz) / (2 * h);
313:   }
314: 
315:   normalAt(x, z, out = new THREE.Vector3()) {
316:     const h = 1.4;
317:     const hl = this.surfaceAt(x - h, z).y, hr = this.surfaceAt(x + h, z).y;
318:     const hd = this.surfaceAt(x, z - h).y, hu = this.surfaceAt(x, z + h).y;
319:     return out.set(hl - hr, 2 * h, hd - hu).normalize();
320:   }
