322:   // ---------------------------------------------------------------- water
323:   _buildWater() {
324:     const seaMat = this._waterMaterial(new THREE.Color(0x082431), new THREE.Color(0x1e6173), 1);
325:     const sea = new THREE.Mesh(new THREE.PlaneGeometry(18000, 18000), seaMat);
326:     sea.rotation.x = -Math.PI / 2;
327:     sea.position.y = 0.15;
328:     sea.receiveShadow = false;
329:     sea.renderOrder = 2;
330:     this.scene.add(sea);
331:     this.water = sea;
332: 
333:     const lakeMat = this._waterMaterial(new THREE.Color(0x0a2a2c), new THREE.Color(0x2b6f65), 0.45);
334:     const lake = new THREE.Mesh(new THREE.CircleGeometry(306, 64), lakeMat);
335:     lake.rotation.x = -Math.PI / 2;
336:     lake.position.set(600, 13.4, -1500);
337:     lake.receiveShadow = false;
338:     this.scene.add(lake);
339:     this.lake = lake;
340:     this.animatedWater.push(seaMat, lakeMat);
341:   }
342: 
343:   _waterMaterial(deep, shallow, scale) {
344:     const uniforms = {
345:       uTime: { value: 0 },
346:       uDeep: { value: deep },
