121:   const wheelR = cfg.wheelR;
122:   const profile = sampleProfile(PROFILES[cfg.profile] || PROFILES.sport, 32);
123:   const paintHex = opts.paint ?? vehicle.color ?? 0xff5a12;
124:   const finish = opts.finish ?? vehicle.finish ?? 'metallic';
125:   const rimStyle = opts.rimStyle ?? (cfg.wheelR > .4 ? 'offroad' : 'split5');
126:   const rimColor = opts.rimColor ?? 0x15171a;
127:   const accentHex = opts.accent ?? (vehicle.stripes ? 0xf2f0e4 : 0x111417);
