133:   const paintMat = makePaint(paintHex, finish);
134:   const glassMat = new THREE.MeshPhysicalMaterial({
135:     color: 0x081116, metalness: 0.1, roughness: 0.04, transparent: true, opacity: 0.66,
136:     envMapIntensity: 2.2, clearcoat: 1, clearcoatRoughness: 0.03, side: THREE.DoubleSide,
137:   });
