139:   const blackMat = new THREE.MeshStandardMaterial({ color: 0x0c0e10, roughness: 0.72, metalness: 0.15 });
140:   const chromeMat = new THREE.MeshStandardMaterial({ color: 0xdce1e5, roughness: 0.09, metalness: 1 });
141:   const interiorMat = new THREE.MeshStandardMaterial({ color: 0x171a1e, roughness: 0.78, metalness: 0.1 });
142:   const accentMat = new THREE.MeshPhysicalMaterial({ color: accentHex, roughness: 0.35, metalness: .35, clearcoat: .7 });
143:   const headlightMat = new THREE.MeshStandardMaterial({ color: 0xf6fbff, emissive: 0xdfefff, emissiveIntensity: 2.2, roughness: .1, metalness: .2 });
144:   const tailMat = new THREE.MeshStandardMaterial({ color: 0x5e0808, emissive: 0xff1208, emissiveIntensity: .9, roughness: .22, metalness: .2 });
145:   const indicatorMat = new THREE.MeshStandardMaterial({ color: 0x6b3c00, emissive: 0xff8a00, emissiveIntensity: 0.2, roughness: .3 });
146:   const reverseMat = new THREE.MeshStandardMaterial({ color: 0xbfc6cc, emissive: 0xe8f4ff, emissiveIntensity: 0.0, roughness: .2 });
147: 
148:   // ---------- body shell via lofted cross sections
149:   const ring = [];
150:   for (const s of profile) {
151:     const [zf, wf, ybf, ysf, ytf, twf] = s;
152:     const w = (Wd / 2) * Math.max(.16, wf);
153:     const b = CL + Math.max(.015, ybf) * (H - CL);
154:     const sh = CL + Math.max(.06, ysf) * (H - CL);
155:     const top = CL + Math.max(.09, ytf) * (H - CL);
156:     const tw = (Wd / 2) * Math.max(.14, twf);
157:     const z = zf * L;
158:     const pts = [
159:       [0, b], [w * .55, b], [w * .90, b + (sh - b) * .05], [w, b + (sh - b) * .30],
160:       [w, sh], [w * .92, sh + (top - sh) * .45], [tw, top], [0, top],
161:       [-tw, top], [-w * .92, sh + (top - sh) * .45], [-w, sh],
162:       [-w, b + (sh - b) * .30], [-w * .90, b + (sh - b) * .05], [-w * .55, b],
163:     ];
164:     ring.push({ z, pts, w, top, sh, b, tw });
165:   }
166:   const positions = [];
167:   const indicesPaint = [];
168:   const indicesGlass = [];
169:   const rings = ring.map(r => r.pts.map(([x, y]) => new THREE.Vector3(x, y, r.z)));
170:   const ringLen = rings[0].length;
171:   rings.forEach(r => r.forEach(p => positions.push(p.x, p.y, p.z)));
172:   const normalsApprox = [];
173:   const tmpA = new THREE.Vector3(), tmpB = new THREE.Vector3(), tmpC = new THREE.Vector3();
174:   for (let j = 0; j < rings.length - 1; j++) {
175:     const zA = ring[j].z, zB = ring[j + 1].z;
176:     const topSlope = Math.abs(ring[j].top - ring[j + 1].top) / Math.max(.001, Math.abs(zB - zA));
177:     for (let i = 0; i < ringLen; i++) {
178:       const i2 = (i + 1) % ringLen;
179:       const a = j * ringLen + i, b = j * ringLen + i2;
180:       const c = (j + 1) * ringLen + i, d = (j + 1) * ringLen + i2;
181:       const pA = rings[j][i], pB = rings[j][i2], pC = rings[j + 1][i];
182:       tmpA.copy(pB).sub(pA); tmpB.copy(pC).sub(pA); tmpC.crossVectors(tmpA, tmpB).normalize();
183:       const ny = Math.abs(tmpC.y);
184:       const zc = (zA + zB) / 2;
185:       const yc = (ring[j].pts[i][1] + ring[j].pts[i2][1] + ring[j + 1].pts[i][1] + ring[j + 1].pts[i2][1]) / 4;
186:       const shc = (ring[j].sh + ring[j + 1].sh) / 2;
187:       const topc = (ring[j].top + ring[j + 1].top) / 2;
188:       const cabin = zc > cfg.cabinRear * L && zc < cfg.cabinFront * L;
189:       const nearRoof = topSlope < .22 && yc > topc - .035;
190:       const greenhouse = cabin && yc > shc - .015 && !nearRoof && (ny < .92 || topSlope > .22);
191:       const idx = greenhouse ? indicesGlass : indicesPaint;
192:       idx.push(a, c, b, b, c, d);
193:       normalsApprox.push(tmpC.clone());
194:     }
195:   }
196:   const geom = new THREE.BufferGeometry();
197:   geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
198:   const paintCount = indicesPaint.length;
199:   const allIdx = indicesPaint.concat(indicesGlass);
200:   geom.setIndex(allIdx);
201:   geom.addGroup(0, paintCount, 0);
202:   geom.addGroup(paintCount, indicesGlass.length, 1);
203:   geom.computeVertexNormals();
204:   geom.computeBoundingSphere();
205:   const shell = new THREE.Mesh(geom, [paintMat, glassMat]);
206:   shell.castShadow = true;
207:   shell.receiveShadow = true;
208:   body.add(shell);
