210:   const topYAt = (z) => {
211:     const zf = clamp01((z / L) + .5);
212:     for (let i = 0; i < ring.length - 1; i++) {
213:       const a = ring[i].pts[0] ? ring[i].z : 0;
214:       const b = ring[i + 1].z;
215:       if (z >= a && z <= b) {
216:         const t = (z - a) / Math.max(.0001, b - a);
217:         return ring[i].top + (ring[i + 1].top - ring[i].top) * t;
218:       }
219:     }
220:     return H;
221:   };
