input.content:
import { clamp } from '../core/noise.js';

const KEY_ACTIONS = {
  KeyW: 'throttle', ArrowUp: 'throttle',
  KeyS: 'brake', ArrowDown: 'brake',
  KeyA: 'left', ArrowLeft: 'left',
  KeyD: 'right', ArrowRight: 'right',
  Space: 'handbrake',
  ShiftLeft: 'boost', ShiftRight: 'boost',
  KeyC: 'camera',
  KeyM: 'map',
  KeyG: 'garage',
  KeyH: 'help',
  KeyR: 'reset',
  Escape: 'pause',
  KeyE: 'interact',
  Enter: 'interact',
  KeyQ: 'shiftDown',
  KeyF: 'favourite',
};

const TOUCH_ACTIONS = ['left', 'right', 'gas', 'brake', 'handbrake'];

export class Input {
  constructor() {
    this.keys = new Set();
    this.touch = new Map();          // action -> pointerId
    this.held = new Set();           // keyboard + touch held actions
    this.queued = new Set();
    this.enabled = true;
    this.sensitivity = 1;
    this.isTouch = window.matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window;
    if (this.isTouch) document.body.classList.add('touch');
    this._bindKeyboard();
    this._bindTouch();
    this._padPrev = {};
    this.pad = null;
  }

  _bindKeyboard() {
    window.addEventListener('keydown', (e) => {
      if (e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA' || e.target.isContentEditable)) return;
      const action = KEY_ACTIONS[e.code];
      if (!action) return;
      if (action === 'map' || action === 'garage' || action === 'pause' || action === 'help' || action === 'interact' || action === 'camera' || action === 'reset') {
        e.preventDefault();
      }
      if (!e.repeat) {
        this.queued.add(action);
        this.held.add(action);
      }
      this.keys.add(e.code);
    }, { passive: false });

    window.addEventListener('keyup', (e) => {
      this.keys.delete(e.code);
      const action = KEY_ACTIONS[e.code];
      if (action) this.held.delete(action);
    });

    window.addEventListener('blur', () => {
      this.keys.clear();
      this.held.clear();
      this.touch.clear();
    });
  }

  _bindTouch() {
    const buttons = document.querySelectorAll('[data-touch]');
    buttons.forEach(btn => {
      const action = btn.dataset.touch;
      const down = (e) => {
        e.preventDefault();
        e.stopPropagation();
        const id = e.pointerId;
        if (action === 'camera') {
          this.queued.add('camera');
          btn.classList.add('down');
          setTimeout(() => btn.classList.remove('down'), 120);
          return;
        }
        if (this.touch.has(action)) return;
        this.touch.set(action, id);
        this.held.add(action === 'gas' ? 'throttle' : action === 'brake' ? 'brake' : action);
        btn.classList.add('down');
        try { btn.setPointerCapture(id); } catch (_) { /* noop */ }
      };
      const up = (e) => {
        e.preventDefault();
        if (this.touch.get(action) === e.pointerId) {
          this.touch.delete(action);
          const mapped = action === 'gas' ? 'throttle' : action === 'brake' ? 'brake' : action;
          if (![...this.touch.keys()].some(a => (a === 'gas' ? 'throttle' : a === 'brake' ? 'brake' : a) === mapped)) {
            this.held.delete(mapped);
          }
          btn.classList.remove('down');
        }
      };
      btn.addEventListener('pointerdown', down);
      btn.addEventListener('pointerup', up);
      btn.addEventListener('pointercancel', up);
      btn.addEventListener('pointerleave', (e) => {
        if (btn.hasPointerCapture && btn.hasPointerCapture(e.pointerId)) return;
        up(e);
      });
      btn.addEventListener('contextmenu', e => e.preventDefault());
    });
    // The canvas and HUD buttons can steal focus; keep touch class in sync.
    window.addEventListener('touchstart', () => {
      if (!document.body.classList.contains('touch')) document.body.classList.add('touch');
    }, { passive: true, once: true });
  }

  setEnabled(on) {
    this.enabled = on;
    if (!on) {
      this.held.clear();
      this.keys.clear();
      this.touch.clear();
      document.querySelectorAll('.touch-btn.down').forEach(b => b.classList.remove('down'));
    }
  }

  pollGamepad() {
    if (!navigator.getGamepads) return;
    const pads = navigator.getGamepads();
    let gp = null;
    for (const p of pads) if (p && p.connected) { gp = p; break; }
    this.pad = gp;
    if (!gp) return;
    const dead = 0.16;
    const ax = gp.axes[0] || 0;
    const steer = Math.abs(ax) > dead ? Math.sign(ax) * ((Math.abs(ax) - dead) / (1 - dead)) : 0;
    if (steer < -0.05) this.held.add('left'); else this.held.delete('left');
    if (steer > 0.05) this.held.add('right'); else this.held.delete('right');
    const rt = gp.buttons[7]?.value || 0;
    const lt = gp.buttons[6]?.value || 0;
    if (rt > 0.08) this.held.add('throttle'); else this.held.delete('throttle');
    if (lt > 0.08) this.held.add('brake'); else this.held.delete('brake');
    if (gp.buttons[0]?.pressed) this.held.add('handbrake'); else this.held.delete('handbrake');
    const edges = { 3: 'camera', 1: 'reset', 9: 'pause', 8: 'map', 2: 'garage' };
    for (const [idx, action] of Object.entries(edges)) {
      const pressed = !!gp.buttons[idx]?.pressed;
      if (pressed && !this._padPrev[idx]) this.queued.add(action);
      this._padPrev[idx] = pressed;
    }
    this.padSteer = steer;
  }

  update() {
    this.pollGamepad();
  }

  get throttle() {
    if (!this.enabled) return 0;
    return this.held.has('throttle') ? 1 : 0;
  }
  get brake() {
    if (!this.enabled) return 0;
    return this.held.has('brake') ? 1 : 0;
  }
  get steer() {
    if (!this.enabled) return 0;
    let v = 0;
    if (this.held.has('left')) v -= 1;
    if (this.held.has('right')) v += 1;
    if (this.padSteer && Math.abs(this.padSteer) > Math.abs(v)) v = this.padSteer;
    return clamp(v * this.sensitivity, -1, 1);
  }
  get handbrake() { return this.enabled && this.held.has('handbrake'); }
  get boost() { return this.enabled && this.held.has('boost'); }
  get anyDrivingInput() {
    return this.throttle > 0 || this.brake > 0 || Math.abs(this.steer) > 0.01 || this.handbrake;
  }

  consume(action) {
    if (!this.queued.has(action)) return false;
    this.queued.delete(action);
    return true;
  }
  clearActions() { this.queued.clear(); }
}

import { clamp } from '../core/noise.js';

/**
 * Lightweight synthesised engine + tyre + wind + rain audio.
 * No audio files, everything is generated with Web Audio so the game
 * remains a single static deployment.
 */
export class AudioSystem {
  constructor() {
    this.ctx = null;
    this.enabled = true;
    this.started = false;
    this.driving = false;
    this.vehicle = null;
    this.master = null;
    this._lastSpeed = 0;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      this.ctx = new AC();
    } catch (_) {
      return;
    }
    const ctx = this.ctx;
    this.master = ctx.createGain();
    this.master.gain.value = 0.0001;
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.knee.value = 20;
    comp.ratio.value = 5;
    comp.attack.value = 0.004;
    comp.release.value = 0.25;
    this.master.connect(comp);
    comp.connect(ctx.destination);

    this._noise = this._makeNoise(2.0);

    // ---- engine
    this.engineGain = ctx.createGain();
    this.engineGain.gain.value = 0.0001;
    this.engineFilter = ctx.createBiquadFilter();
    this.engineFilter.type = 'lowpass';
    this.engineFilter.frequency.value = 1200;
    this.engineFilter.Q.value = 0.8;
    this.engineGain.connect(this.engineFilter);
    this.engineFilter.connect(this.master);

    const shaper = ctx.createWaveShaper();
    const curve = new Float32Array(1024);
    for (let i = 0; i < 1024; i++) {
      const x = (i / 1023) * 2 - 1;
      curve[i] = Math.tanh(x * 2.2) * 0.75;
    }
    shaper.curve = curve;
    shaper.oversample = '2x';
    this.engineFilter.disconnect();
    this.engineFilter.connect(shaper);
    shaper.connect(this.master);

    this.osc1 = ctx.createOscillator();
    this.osc1.type = 'sawtooth';
    this.osc1.frequency.value = 70;
    this.osc1Gain = ctx.createGain();
    this.osc1Gain.gain.value = 0.32;
    this.osc1.connect(this.osc1Gain);
    this.osc1Gain.connect(this.engineGain);
    this.osc1.start();

    this.osc2 = ctx.createOscillator();
    this.osc2.type = 'square';
    this.osc2.frequency.value = 105;
    this.osc2.detune.value = 7;
    this.osc2Gain = ctx.createGain();
    this.osc2Gain.gain.value = 0.13;
    this.osc2.connect(this.osc2Gain);
    this.osc2Gain.connect(this.engineGain);
    this.osc2.start();

    this.osc3 = ctx.createOscillator();
    this.osc3.type = 'sine';
    this.osc3.frequency.value = 35;
    this.osc3Gain = ctx.createGain();
    this.osc3Gain.gain.value = 0.22;
    this.osc3.connect(this.osc3Gain);
    this.osc3Gain.connect(this.master);
    this.osc3.start();

    // exhaust rasp
    this.exhaust = ctx.createBufferSource();
    this.exhaust.buffer = this._noise;
    this.exhaust.loop = true;
    this.exhaustFilter = ctx.createBiquadFilter();
    this.exhaustFilter.type = 'bandpass';
    this.exhaustFilter.frequency.value = 240;
    this.exhaustFilter.Q.value = 0.7;
    this.exhaustGain = ctx.createGain();
    this.exhaustGain.gain.value = 0.0001;
    this.exhaust.connect(this.exhaustFilter);
    this.exhaustFilter.connect(this.exhaustGain);
    this.exhaustGain.connect(this.master);
    this.exhaust.start();

    // tyre scrub
    this.tyre = ctx.createBufferSource();
    this.tyre.buffer = this._noise;
    this.tyre.loop = true;
    this.tyreFilter = ctx.createBiquadFilter();
    this.tyreFilter.type = 'bandpass';
    this.tyreFilter.frequency.value = 900;
    this.tyreFilter.Q.value = 1.1;
    this.tyreGain = ctx.createGain();
    this.tyreGain.gain.value = 0.0001;
    this.tyre.connect(this.tyreFilter);
    this.tyreFilter.connect(this.tyreGain);
    this.tyreGain.connect(this.master);
    this.tyre.start();

    // wind
    this.wind = ctx.createBufferSource();
    this.wind.buffer = this._noise;
    this.wind.loop = true;
    this.windFilter = ctx.createBiquadFilter();
    this.windFilter.type = 'lowpass';
    this.windFilter.frequency.value = 520;
    this.windGain = ctx.createGain();
    this.windGain.gain.value = 0.0001;
    this.wind.connect(this.windFilter);
    this.windFilter.connect(this.windGain);
    this.windGain.connect(this.master);
    this.wind.start();

    // rain
    this.rain = ctx.createBufferSource();
    this.rain.buffer = this._noise;
    this.rain.loop = true;
    this.rainFilter = ctx.createBiquadFilter();
    this.rainFilter.type = 'highpass';
    this.rainFilter.frequency.value = 1400;
    this.rainGain = ctx.createGain();
    this.rainGain.gain.value = 0.0001;
    this.rain.connect(this.rainFilter);
    this.rainFilter.connect(this.rainGain);
    this.rainGain.connect(this.master);
    this.rain.start();

    this.started = true;
    const target = this.enabled ? 0.72 : 0.0001;
    this.master.gain.setTargetAtTime(target, ctx.currentTime, 0.2);
  }

  _makeNoise(seconds) {
    const ctx = this.ctx;
    const len = Math.floor(ctx.sampleRate * seconds);
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = 0.96 * last + 0.04 * white;
      d[i] = last * 2.4 + white * 0.35;
    }
    return buf;
  }

  setEnabled(on) {
    this.enabled = on;
    if (!this.ctx) return;
    this.master.gain.setTargetAtTime(on ? 0.72 : 0.0001, this.ctx.currentTime, 0.15);
  }

  setDriving(on) {
    this.driving = on;
    if (!on && this.ctx) {
      const t = this.ctx.currentTime;
      this.engineGain.gain.setTargetAtTime(0.0001, t, 0.1);
      this.exhaustGain.gain.setTargetAtTime(0.0001, t, 0.1);
      this.tyreGain.gain.setTargetAtTime(0.0001, t, 0.1);
      this.windGain.gain.setTargetAtTime(0.0001, t, 0.1);
    }
  }

  setVehicle(vehicle) {
    this.vehicle = vehicle;
    if (!this.ctx) return;
    const cylinders = vehicle?.engine?.cylinders || 6;
    this.cylinders = cylinders;
    this.osc2.type = cylinders >= 10 ? 'sawtooth' : 'square';
    this.osc1.detune.value = cylinders === 0 ? 1200 : 0;
    this.osc3Gain.gain.setTargetAtTime(cylinders === 0 ? 0.04 : 0.2, this.ctx.currentTime, 0.2);
  }

  update(dt, state) {
    if (!this.ctx || !this.started || !this.enabled) return;
    if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
    const t = this.ctx.currentTime;
    const v = this.vehicle || {};
    const cylinders = v.engine?.cylinders || this.cylinders || 6;
    const ev = cylinders === 0;
    const rpmNorm = clamp(((state.rpm || 900) - 800) / 7200, 0, 1);
    const speedNorm = clamp((state.speed || 0) / 330, 0, 1);
    const firing = ev ? 50 + rpmNorm * 210 : (34 + rpmNorm * 120) * (cylinders / 6);
    const active = this.driving;

    this.osc1.frequency.setTargetAtTime(firing, t, 0.045);
    this.osc2.frequency.setTargetAtTime(firing * 1.5 + 2, t, 0.05);
    this.osc3.frequency.setTargetAtTime(firing * 0.5, t, 0.06);
    this.engineFilter.frequency.setTargetAtTime(520 + rpmNorm * 2200 + (state.throttle || 0) * 900, t, 0.08);
    const engineVol = active ? (0.026 + (state.throttle || 0) * 0.045 + rpmNorm * 0.016) : 0.0001;
    this.engineGain.gain.setTargetAtTime(engineVol, t, 0.07);
    this.exhaustGain.gain.setTargetAtTime(active ? 0.012 + (state.throttle || 0) * 0.028 : 0.0001, t, 0.08);
    this.exhaustFilter.frequency.setTargetAtTime(180 + rpmNorm * 600, t, 0.08);

    const dirt = state.surface === 'dirt' || state.surface === 'terrain' ? 1.25 : 1;
    const slip = clamp((state.slip || 0) / 16, 0, 1);
    const tyreVol = active ? clamp(speedNorm * 0.018 + slip * 0.1, 0, 0.12) * dirt : 0.0001;
    this.tyreGain.gain.setTargetAtTime(tyreVol, t, 0.06);
    this.tyreFilter.frequency.setTargetAtTime(700 + slip * 1600 + speedNorm * 500, t, 0.08);

    const windVol = active ? speedNorm * speedNorm * 0.07 : 0.0001;
    this.windGain.gain.setTargetAtTime(windVol, t, 0.1);
    this.windFilter.frequency.setTargetAtTime(300 + speedNorm * 950, t, 0.1);
    this.rainGain.gain.setTargetAtTime(state.rain ? 0.032 : 0.0001, t, 0.25);

    if (Math.abs((state.speed || 0) - this._lastSpeed) > 45) this._lastSpeed = state.speed || 0;
  }

  beep(freq = 880, dur = 0.09, type = 'sine', vol = 0.08) {
    if (!this.ctx || !this.enabled) return;
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(this.master);
    o.start(t); o.stop(t + dur + 0.03);
  }

  ui() { this.beep(680, 0.045, 'triangle', 0.035); }
  shift() { this.beep(240, 0.035, 'square', 0.03); }
  countdown(final = false) {
    this.beep(final ? 1320 : 760, final ? 0.3 : 0.12, 'sine', final ? 0.12 : 0.07);
  }
  checkpoint() { this.beep(1040, 0.08, 'triangle', 0.06); setTimeout(() => this.beep(1380, 0.1, 'triangle', 0.05), 70); }
  collect() {
    this.beep(880, 0.08, 'triangle', 0.055);
    setTimeout(() => this.beep(1320, 0.12, 'triangle', 0.05), 80);
  }
  finish(gold = false) {
    const notes = gold ? [660, 880, 1100, 1480] : [520, 660, 880];
    notes.forEach((n, i) => setTimeout(() => this.beep(n, 0.18, 'triangle', 0.07), i * 110));
  }
  impact(strength = 0.5) {
    if (!this.ctx || !this.enabled) return;
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = 'sine';
    o.frequency.setValueAtTime(80, t);
    o.frequency.exponentialRampToValueAtTime(28, t + 0.25);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.12 * clamp(strength, 0.1, 1), t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.3);
    o.connect(g); g.connect(this.master);
    o.start(t); o.stop(t + 0.32);
  }
}

import * as THREE from 'three';
import { clamp } from '../core/noise.js';

const MAX_PARTICLES = 320;
const MAX_SKID = 280;
const MAX_DROPS = 800;

export class EffectsSystem {
  constructor(scene, engine, world) {
    this.scene = scene;
    this.engine = engine;
    this.world = world;
    this.motionEnabled = true;
    this.smokeAcc = 0;
    this.dustAcc = 0;
    this.skidCursor = 0;
    this.skidLast = [null, null];
    this.skidActive = [false, false];
    this.particles = [];
    this._buildSmoke();
    this._buildSkids();
    this._buildRain();
    this.speedEl = document.getElementById('speedlines');
    this.vignetteEl = document.getElementById('vignette');
  }

  _buildSmoke() {
    const geo = new THREE.BufferGeometry();
    this.pPos = new Float32Array(MAX_PARTICLES * 3);
    this.pSize = new Float32Array(MAX_PARTICLES);
    this.pAlpha = new Float32Array(MAX_PARTICLES);
    this.pColor = new Float32Array(MAX_PARTICLES * 3);
    for (let i = 0; i < MAX_PARTICLES; i++) {
      this.pPos[i * 3 + 1] = -1000;
      this.pAlpha[i] = 0;
    }
    geo.setAttribute('position', new THREE.BufferAttribute(this.pPos, 3));
    geo.setAttribute('aSize', new THREE.BufferAttribute(this.pSize, 1));
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.pAlpha, 1));
    geo.setAttribute('aColor', new THREE.BufferAttribute(this.pColor, 3));
    geo.setDrawRange(0, MAX_PARTICLES);
    const mat = new THREE.ShaderMaterial({
      transparent: true,
      depthWrite: false,
      blending: THREE.NormalBlending,
      uniforms: {},
      vertexShader: `
        attribute float aSize;
        attribute float aAlpha;
        attribute vec3 aColor;
        varying float vAlpha;
        varying vec3 vColor;
        void main(){
          vAlpha = aAlpha;
          vColor = aColor;
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = aSize * (360.0 / max(1.0, -mv.z));
          gl_Position = projectionMatrix * mv;
        }`,
      fragmentShader: `
        varying float vAlpha;
        varying vec3 vColor;
        void main(){
          vec2 p = gl_PointCoord - .5;
          float d = length(p);
          float a = smoothstep(.5, .06, d) * vAlpha;
          if (a < .004) discard;
          gl_FragColor = vec4(vColor, a);
          #include <tonemapping_fragment>
          #include <colorspace_fragment>
        }`,
    });
    this.smoke = new THREE.Points(geo, mat);
    this.smoke.frustumCulled = false;
    this.smoke.renderOrder = 5;
    this.scene.add(this.smoke);
    for (let i = 0; i < MAX_PARTICLES; i++) {
      this.particles.push({ life: 0, max: 1, vx: 0, vy: 0, vz: 0, size: 1, alpha: 0, grow: 0, drag: 0 });
    }
  }

  _particleColor(c) { return new THREE.Color(c); }

  _spawn(x, y, z, color, size, life, vx, vy, vz, alpha = 0.5, grow = 0.7) {
    const i = this._pCursor = ((this._pCursor ?? -1) + 1) % MAX_PARTICLES;
    const p = this.particles[i];
    p.life = life; p.max = life; p.vx = vx; p.vy = vy; p.vz = vz;
    p.size = size; p.alpha = alpha; p.grow = grow; p.drag = 1.7;
    this.pPos[i * 3] = x; this.pPos[i * 3 + 1] = y; this.pPos[i * 3 + 2] = z;
    const col = color instanceof THREE.Color ? color : this._particleColor(color);
    this.pColor[i * 3] = col.r; this.pColor[i * 3 + 1] = col.g; this.pColor[i * 3 + 2] = col.b;
    this.pSize[i] = size;
    this.pAlpha[i] = alpha;
  }

  _buildSkids() {
    const geo = new THREE.BufferGeometry();
    const pos = new Float32Array(MAX_SKID * 4 * 3);
    for (let i = 0; i < pos.length; i += 3) pos[i + 1] = -1000;
    const idx = new Uint16Array(MAX_SKID * 6);
    for (let i = 0; i < MAX_SKID; i++) {
      const a = i * 4;
      idx[i * 6] = a; idx[i * 6 + 1] = a + 2; idx[i * 6 + 2] = a + 1;
      idx[i * 6 + 3] = a + 1; idx[i * 6 + 4] = a + 2; idx[i * 6 + 5] = a + 3;
    }
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setIndex(new THREE.BufferAttribute(idx, 1));
    geo.setDrawRange(0, MAX_SKID * 6);
    this.skidPos = pos;
    this.skidGeo = geo;
    const mat = new THREE.MeshBasicMaterial({
      color: 0x050505, transparent: true, opacity: 0.42, depthWrite: false,
      polygonOffset: true, polygonOffsetFactor: -3, polygonOffsetUnits: -3,
    });
    this.skids = new THREE.Mesh(geo, mat);
    this.skids.frustumCulled = false;
    this.skids.renderOrder = 3;
    this.scene.add(this.skids);
  }

  _buildRain() {
    const geo = new THREE.BufferGeometry();
    const pos = new Float32Array(MAX_DROPS * 2 * 3);
    for (let i = 0; i < pos.length; i += 3) pos[i + 1] = -1000;
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    this.rainPos = pos;
    this.rainGeo = geo;
    const mat = new THREE.LineBasicMaterial({ color: 0xb4d2e6, transparent: true, opacity: 0.36, depthWrite: false });
    this.rain = new THREE.LineSegments(geo, mat);
    this.rain.frustumCulled = false;
    this.rain.renderOrder = 6;
    this.scene.add(this.rain);
    this.drops = [];
    for (let i = 0; i < MAX_DROPS; i++) {
      this.drops.push({ x: 0, y: -1000, z: 0, v: 26 + Math.random() * 18, len: 0.7 + Math.random() * 1.1 });
    }
    this._rainInit = false;
  }

  update(dt, player, camera) {
    if (!player || !player.model) return;
    const speed = player.speedKmh;
    const slip = player.slip + (player.handbrake ? 5 : 0);
    const surface = player.surface || {};
    const onDirt = !surface.onRoad || surface.type === 'dirt';
    const pos = player.pos;
    const heading = player.heading;
    const right = { x: Math.cos(heading), z: -Math.sin(heading) };
    const fwd = { x: Math.sin(heading), z: Math.cos(heading) };
    const track = player.dims.track;

    // ---- smoke / dust from the rear tyres
    if (!player.airborne && speed > 12) {
      const emitting = slip > 2.2 || (player.handbrake && speed > 8);
      if (emitting || (onDirt && speed > 18)) {
        const rate = emitting ? 24 + Math.min(30, slip * 3) : 8;
        this.smokeAcc += dt * rate;
        while (this.smokeAcc > 1) {
          this.smokeAcc -= 1;
          const side = Math.random() > 0.5 ? 1 : -1;
          const x = pos.x + right.x * side * track * 0.48 - fwd.x * player.dims.wheelbase * 0.46;
          const z = pos.z + right.z * side * track * 0.48 - fwd.z * player.dims.wheelbase * 0.46;
          const y = (surface.y || pos.y) + 0.1 + Math.random() * 0.2;
          const col = emitting ? (surface.type === 'dirt' ? 0x8d7557 : 0xb9bcc0) : 0x9b8465;
          this._spawn(
            x, y, z, col,
            0.75 + Math.random() * 0.55,
            0.7 + Math.random() * 0.8,
            (Math.random() - 0.5) * 2.4 - fwd.x * 2.2,
            0.45 + Math.random() * 1.2,
            (Math.random() - 0.5) * 2.4 - fwd.z * 2.2,
            emitting ? 0.42 : 0.24, 1.7,
          );
        }
      }
    }

    // ---- skid marks
    const skidding = !player.airborne && speed > 8 && (slip > 2.4 || player.handbrake || (surface.type === 'dirt' && slip > 1.2));
    for (let side = 0; side < 2; side++) {
      const s = side === 0 ? 1 : -1;
      const x = pos.x + right.x * s * track * 0.47 - fwd.x * player.dims.wheelbase * 0.47;
      const z = pos.z + right.z * s * track * 0.47 - fwd.z * player.dims.wheelbase * 0.47;
      const y = (surface.y || pos.y) + 0.035;
      if (!skidding) { this.skidActive[side] = false; this.skidLast[side] = null; continue; }
      const last = this.skidLast[side];
      if (!last) { this.skidLast[side] = { x, z, y }; this.skidActive[side] = true; continue; }
      const dx = x - last.x, dz = z - last.z;
      const d = Math.hypot(dx, dz);
      if (d < 0.22) continue;
      if (d > 3.2) { this.skidLast[side] = { x, z, y }; continue; }
      const nx = -dz / d * 0.14, nz = dx / d * 0.14;
      const o = this.skidCursor * 12;
      const p = this.skidPos;
      p[o] = last.x + nx; p[o + 1] = last.y; p[o + 2] = last.z + nz;
      p[o + 3] = last.x - nx; p[o + 4] = last.y; p[o + 5] = last.z - nz;
      p[o + 6] = x + nx; p[o + 7] = y; p[o + 8] = z + nz;
      p[o + 9] = x - nx; p[o + 10] = y; p[o + 11] = z - nz;
      this.skidGeo.attributes.position.needsUpdate = true;
      this.skidCursor = (this.skidCursor + 1) % MAX_SKID;
      this.skidLast[side] = { x, z, y };
    }

    // ---- particles
    const pa = this.smoke.geometry.attributes;
    for (let i = 0; i < MAX_PARTICLES; i++) {
      const p = this.particles[i];
      if (p.life <= 0) { if (this.pAlpha[i] !== 0) this.pAlpha[i] = 0; continue; }
      p.life -= dt;
      if (p.life <= 0) {
        this.pAlpha[i] = 0;
        this.pPos[i * 3 + 1] = -1000;
        continue;
      }
      const damp = Math.exp(-p.drag * dt);
      p.vx *= damp; p.vz *= damp;
      p.vy = p.vy * damp + 0.65 * dt;
      this.pPos[i * 3] += p.vx * dt;
      this.pPos[i * 3 + 1] += p.vy * dt;
      this.pPos[i * 3 + 2] += p.vz * dt;
      const lifeT = p.life / p.max;
      this.pAlpha[i] = p.alpha * Math.pow(lifeT, 0.8) * Math.min(1, (1 - lifeT) * 8);
      this.pSize[i] = p.size * (1 + (1 - lifeT) * p.grow);
    }
    pa.position.needsUpdate = true;
    pa.aSize.needsUpdate = true;
    pa.aAlpha.needsUpdate = true;
    pa.aColor.needsUpdate = true;

    // ---- rain
    const raining = this.engine.weather === 'rain';
    this.rain.visible = raining;
    if (raining) {
      const cx = camera ? camera.position.x : pos.x;
      const cy = camera ? camera.position.y : pos.y + 3;
      const cz = camera ? camera.position.z : pos.z;
      if (!this._rainInit) {
        for (const d of this.drops) {
          d.x = cx + (Math.random() - 0.5) * 70;
          d.y = cy + Math.random() * 32 - 8;
          d.z = cz + (Math.random() - 0.5) * 70;
        }
        this._rainInit = true;
      }
      for (let i = 0; i < MAX_DROPS; i++) {
        const d = this.drops[i];
        d.y -= d.v * dt;
        d.x += 3.2 * dt;
        if (d.y < cy - 12 || Math.abs(d.x - cx) > 44 || Math.abs(d.z - cz) > 44) {
          d.x = cx + (Math.random() - 0.5) * 66;
          d.y = cy + 14 + Math.random() * 18;
          d.z = cz + (Math.random() - 0.5) * 66;
        }
        const o = i * 6;
        this.rainPos[o] = d.x; this.rainPos[o + 1] = d.y; this.rainPos[o + 2] = d.z;
        this.rainPos[o + 3] = d.x - 0.08; this.rainPos[o + 4] = d.y - d.len; this.rainPos[o + 5] = d.z - 0.03;
      }
      this.rainGeo.attributes.position.needsUpdate = true;
    } else {
      this._rainInit = false;
    }

    // ---- screen speed effects
    if (this.speedEl) {
      const on = this.motionEnabled && speed > 205 && !player.airborne;
      this.speedEl.classList.toggle('on', on);
      if (on) this.speedEl.style.opacity = String(clamp((speed - 205) / 140, 0.1, 0.85));
    }
    if (this.vignetteEl) this.vignetteEl.classList.toggle('hot', this.motionEnabled && speed > 230);
  }

  setMotion(on) {
    this.motionEnabled = on;
    if (!on && this.speedEl) this.speedEl.classList.remove('on');
    if (!on && this.vignetteEl) this.vignetteEl.classList.remove('hot');
  }

  clearSkids() {
    for (let i = 0; i < this.skidPos.length; i += 3) this.skidPos[i + 1] = -1000;
    this.skidGeo.attributes.position.needsUpdate = true;
    this.skidLast = [null, null];
  }
}

import * as THREE from 'three';
import { clamp } from '../core/noise.js';

/**
 * Checkpoint race director. The player is placed on the event grid,
 * gets a short countdown, then must pass every gate in order.
 */
export class RaceManager {
  constructor(world, save, callbacks = {}) {
    this.world = world;
    this.save = save;
    this.callbacks = callbacks;
    this.state = 'idle';
    this.event = null;
    this.time = 0;
    this.countdown = 0;
    this.cpIndex = 0;
    this.result = null;
    this._lastCount = 0;
    this._buildBeacon();
  }

  _buildBeacon() {
    const g = new THREE.Group();
    const beamMat = new THREE.MeshBasicMaterial({
      color: 0x35e6ff, transparent: true, opacity: 0.18, depthWrite: false,
      blending: THREE.AdditiveBlending, side: THREE.DoubleSide,
    });
    const beam = new THREE.Mesh(new THREE.CylinderGeometry(2.1, 3.2, 44, 16, 1, true), beamMat);
    beam.position.y = 22;
    g.add(beam);
    const ringMat = new THREE.MeshBasicMaterial({ color: 0xffb648, transparent: true, opacity: 0.85, depthWrite: false, blending: THREE.AdditiveBlending });
    const ring = new THREE.Mesh(new THREE.TorusGeometry(4.4, 0.28, 6, 26), ringMat);
    ring.rotation.x = Math.PI / 2;
    ring.position.y = 1.3;
    g.add(ring);
    const ring2 = new THREE.Mesh(new THREE.TorusGeometry(6.2, 0.14, 5, 30), ringMat);
    ring2.rotation.x = Math.PI / 2;
    ring2.position.y = 1.3;
    g.add(ring2);
    g.visible = false;
    g.renderOrder = 7;
    this.world.scene.add(g);
    this.beacon = g;
    this.beam = beam;
    this.rings = [ring, ring2];
  }

  start(event, player) {
    this.event = event;
    this.player = player;
    this.state = 'countdown';
    this.time = 0;
    this.countdown = 3.65;
    this.cpIndex = 0;
    this.result = null;
    this._lastCount = 4;
    const s = event.start;
    player.placeAt(s.x, s.z, s.heading);
    player.velForward = 0;
    player.velLateral = 0;
    this._placeBeacon(0);
    if (this.callbacks.onStart) this.callbacks.onStart(event);
  }

  _placeBeacon(index) {
    const pts = this.event?.points;
    if (!pts) { this.beacon.visible = false; return; }
    const p = pts[clamp(index, 0, pts.length - 1)];
    this.beacon.visible = true;
    this.beacon.position.set(p.x, p.y || 0.2, p.z);
  }

  update(dt, player) {
    if (this.state === 'idle' || this.state === 'finished') return;
    if (!this.event || !player) return;
    if (this.state === 'countdown') {
      this.countdown -= dt;
      const n = Math.ceil(this.countdown);
      if (n !== this._lastCount && n >= 0 && n <= 3) {
        this._lastCount = n;
        if (this.callbacks.onCountdown) this.callbacks.onCountdown(n);
      }
      if (this.countdown <= 0) {
        this.state = 'racing';
        this.time = 0;
        this.cpIndex = 1;
        this._placeBeacon(1);
        if (this.callbacks.onGo) this.callbacks.onGo(this.event);
      }
      return;
    }

    this.time += dt;

    // animated checkpoint marker
    if (this.beacon.visible) {
      const t = this.time + this.countdown;
      this.rings[0].scale.setScalar(1 + Math.sin(t * 3.2) * 0.08);
      this.rings[1].rotation.z = t * 0.7;
      this.beam.material.opacity = 0.12 + Math.abs(Math.sin(t * 2.4)) * 0.1;
    }

    const pts = this.event.points;
    const next = pts[this.cpIndex];
    if (!next) { this._finish(player); return; }
    const dx = next.x - player.pos.x;
    const dz = next.z - player.pos.z;
    const d = Math.hypot(dx, dz);
    this.nextDistance = d;
    if (d < 21) {
      this.cpIndex++;
      if (this.cpIndex >= pts.length) {
        this._finish(player);
      } else {
        this._placeBeacon(this.cpIndex);
        if (this.callbacks.onCheckpoint) this.callbacks.onCheckpoint(this.cpIndex, pts.length, this.event);
      }
    }
  }

  _finish(player) {
    this.state = 'finished';
    this.beacon.visible = false;
    const event = this.event;
    const time = this.time;
    const target = event.target;
    const grade = time <= target ? 'gold' : time <= target * 1.14 ? 'silver' : 'bronze';
    const mult = grade === 'gold' ? 1 : grade === 'silver' ? 0.65 : 0.4;
    const reward = Math.round(event.reward * mult);
    const prevBest = this.save.bestTimes?.[event.id];
    const newBest = !prevBest || time < prevBest;
    if (newBest) {
      this.save.bestTimes = this.save.bestTimes || {};
      this.save.bestTimes[event.id] = time;
    }
    this.save.credits = (this.save.credits || 0) + reward;
    this.save.wins = (this.save.wins || 0) + (grade === 'gold' ? 1 : 0);
    this.result = { event, time, target, grade, reward, newBest, cp: event.points.length };
    this._placeBeacon(0);
    this.beacon.visible = false;
    if (this.callbacks.onFinish) this.callbacks.onFinish(this.result);
  }

  getHud() {
    if (!this.event) return null;
    const pts = this.event.points;
    const next = pts[Math.min(this.cpIndex, pts.length - 1)];
    const d = next && this.player ? Math.hypot(next.x - this.player.pos.x, next.z - this.player.pos.z) : 0;
    return {
      label: this.event.name.toUpperCase(),
      state: this.state,
      time: this.time,
      countdown: this.countdown,
      cp: Math.max(1, Math.min(this.cpIndex, pts.length - 1)),
      total: pts.length - 1,
      distance: this.state === 'racing' ? d : 0,
      progress: this.state === 'racing' ? clamp((this.cpIndex - 1) / Math.max(1, pts.length - 2), 0, 1) : 0,
    };
  }

  abort() {
    this.state = 'idle';
    this.event = null;
    this.beacon.visible = false;
  }
}

import * as THREE from 'three';
import { clamp } from '../core/noise.js';

const TRAFFIC_COLORS = [0xd7d9da, 0x1b1e22, 0x9aa0a5, 0x7e2d2d, 0x2d466d, 0xd9c7a2, 0x485b4a, 0xbc5b28, 0xe7e9ea, 0x33383d, 0x8e2f59, 0x2b6d70];

/** Low-poly ambient traffic cruising the island's highway and city network. */
export class TrafficSystem {
  constructor(world, engine, count = 44) {
    this.world = world;
    this.engine = engine;
    this.count = count;
    this.cars = [];
    this._mat = new THREE.Matrix4();
    this._q = new THREE.Quaternion();
    this._p = new THREE.Vector3();
    this._s = new THREE.Vector3(1, 1, 1);
    this._build();
  }

  _routes() {
    const roads = this.world.roads.roads.filter(r => ['highway', 'arterial', 'city', 'rural'].includes(r.type) && r.points.length > 6);
    const ring = this.world.roads.byName.get('Horizon Ring');
    const out = [];
    for (let i = 0; i < this.count; i++) {
      const road = i < this.count * 0.34 && ring ? ring : roads[Math.floor(Math.random() * roads.length)];
      out.push(road);
    }
    return out;
  }

  _build() {
    const bodyGeo = new THREE.BoxGeometry(1.78, 0.62, 4.0);
    bodyGeo.translate(0, 0.58, 0);
    const cabinGeo = new THREE.BoxGeometry(1.6, 0.54, 2.0);
    cabinGeo.translate(0, 1.13, -0.18);
    const wheelGeo = [];
    const wheel = new THREE.CylinderGeometry(0.31, 0.31, 0.2, 9);
    wheel.rotateZ(Math.PI / 2);
    for (const x of [-0.79, 0.79]) for (const z of [-1.28, 1.28]) {
      const g = wheel.clone();
      g.translate(x, 0.31, z);
      wheelGeo.push(g);
    }
    const wheelsGeo = mergeSimple(wheelGeo);
    const headGeo = new THREE.BoxGeometry(1.25, 0.09, 0.05);
    headGeo.translate(0, 0.62, 2.02);
    const tailGeo = new THREE.BoxGeometry(1.3, 0.075, 0.05);
    tailGeo.translate(0, 0.66, -2.02);

    const bodyMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.38, metalness: 0.55 });
    const glassMat = new THREE.MeshStandardMaterial({ color: 0x101820, roughness: 0.14, metalness: 0.55 });
    const wheelMat = new THREE.MeshStandardMaterial({ color: 0x0b0d0f, roughness: 0.92 });
    const headMat = new THREE.MeshStandardMaterial({ color: 0xe8f4ff, emissive: 0xbddfff, emissiveIntensity: 1.8 });
    const tailMat = new THREE.MeshStandardMaterial({ color: 0x5b0909, emissive: 0xff160c, emissiveIntensity: 1.4 });
    this.engine.addLampMaterial(headMat);
    this.engine.addLampMaterial(tailMat);

    this.bodyMesh = new THREE.InstancedMesh(bodyGeo, bodyMat, this.count);
    this.cabinMesh = new THREE.InstancedMesh(cabinGeo, glassMat, this.count);
    this.wheelMesh = new THREE.InstancedMesh(wheelsGeo, wheelMat, this.count);
    this.headMesh = new THREE.InstancedMesh(headGeo, headMat, this.count);
    this.tailMesh = new THREE.InstancedMesh(tailGeo, tailMat, this.count);
    [this.bodyMesh, this.cabinMesh, this.wheelMesh, this.headMesh, this.tailMesh].forEach(m => {
      m.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
      m.frustumCulled = false;
      m.castShadow = false;
      m.receiveShadow = false;
    });
    this.bodyMesh.castShadow = true;
    this.routes = this._routes();
    for (let i = 0; i < this.count; i++) {
      const road = this.routes[i];
      const type = road.type;
      const speed = type === 'highway' ? 24 + Math.random() * 12 :
        type === 'arterial' ? 15 + Math.random() * 8 :
        type === 'city' ? 8 + Math.random() * 7 : 12 + Math.random() * 9;
      const car = {
        road,
        seg: Math.floor(Math.random() * road.points.length),
        frac: Math.random(),
        speed,
        dir: Math.random() > 0.5 ? 1 : -1,
        lane: (Math.random() > 0.5 ? 1 : -1) * road.width * 0.21,
        color: new THREE.Color(TRAFFIC_COLORS[i % TRAFFIC_COLORS.length]),
        x: 0, y: 0, z: 0, heading: 0,
      };
      this.bodyMesh.setColorAt(i, car.color);
      this.cars.push(car);
    }
    this.bodyMesh.instanceColor.needsUpdate = true;
    this.world.scene.add(this.bodyMesh, this.cabinMesh, this.wheelMesh, this.headMesh, this.tailMesh);
    for (let i = 0; i < this.count; i++) this._place(i);
    [this.bodyMesh, this.cabinMesh, this.wheelMesh, this.headMesh, this.tailMesh].forEach(m => { m.instanceMatrix.needsUpdate = true; });
  }

  _place(i) {
    const c = this.cars[i];
    const pts = c.road.points;
    const n = pts.length;
    const a = pts[c.seg % n], b = pts[(c.seg + 1) % n];
    const dx = b.x - a.x, dz = b.z - a.z;
    const len = Math.hypot(dx, dz) || 1;
    const px = a.x + (b.x - a.x) * c.frac;
    const pz = a.z + (b.z - a.z) * c.frac;
    const py = a.y + (b.y - a.y) * c.frac;
    const heading = Math.atan2(dx, dz) + (c.dir < 0 ? Math.PI : 0);
    const rx = Math.cos(heading), rz = -Math.sin(heading);
    c.x = px + rx * c.lane;
    c.z = pz + rz * c.lane;
    c.y = py + 0.08;
    c.heading = heading;
    c.len = len;
    this._q.setFromAxisAngle(new THREE.Vector3(0, 1, 0), heading);
    this._p.set(c.x, c.y, c.z);
    this._s.set(1, 1, 1);
    this._mat.compose(this._p, this._q, this._s);
    this.bodyMesh.setMatrixAt(i, this._mat);
    this.cabinMesh.setMatrixAt(i, this._mat);
    this.wheelMesh.setMatrixAt(i, this._mat);
    this.headMesh.setMatrixAt(i, this._mat);
    this.tailMesh.setMatrixAt(i, this._mat);
  }

  update(dt) {
    if (!this.cars.length) return;
    for (let i = 0; i < this.cars.length; i++) {
      const c = this.cars[i];
      const pts = c.road.points;
      const n = pts.length;
      c.frac += (c.dir * c.speed * dt) / Math.max(1, c.len);
      while (c.frac >= 1) {
        c.frac -= 1;
        c.seg = (c.seg + 1) % n;
        if (!c.road.closed && c.seg === 0) c.dir = 1;
      }
      while (c.frac < 0) {
        c.frac += 1;
        c.seg = (c.seg - 1 + n) % n;
        if (!c.road.closed && c.seg === n - 1) c.dir = -1;
      }
      const a = pts[c.seg % n], b = pts[(c.seg + 1) % n];
      c.len = Math.hypot(b.x - a.x, b.z - a.z) || 1;
      this._place(i);
    }
    this.bodyMesh.instanceMatrix.needsUpdate = true;
    this.cabinMesh.instanceMatrix.needsUpdate = true;
    this.wheelMesh.instanceMatrix.needsUpdate = true;
    this.headMesh.instanceMatrix.needsUpdate = true;
    this.tailMesh.instanceMatrix.needsUpdate = true;
  }

  /** Returns a push vector if the player overlaps a traffic car. */
  hit(pos, radius = 2.3) {
    for (const c of this.cars) {
      const dx = pos.x - c.x, dz = pos.z - c.z;
      const d = Math.hypot(dx, dz);
      if (d < radius + 1.15) {
        const overlap = (radius + 1.15 - d);
        if (d < 0.001) return { x: overlap, z: 0 };
        return { x: (dx / d) * overlap, z: (dz / d) * overlap };
      }
    }
    return null;
  }
}

function mergeSimple(geos) {
  const merged = new THREE.BufferGeometry();
  const positions = [];
  const normals = [];
  const uvs = [];
  const indices = [];
  let offset = 0;
  for (const g of geos) {
    const p = g.attributes.position;
    const n = g.attributes.normal;
    const u = g.attributes.uv;
    for (let i = 0; i < p.count; i++) {
      positions.push(p.getX(i), p.getY(i), p.getZ(i));
      if (n) normals.push(n.getX(i), n.getY(i), n.getZ(i));
      if (u) uvs.push(u.getX(i), u.getY(i));
    }
    const idx = g.index;
    if (idx) for (let i = 0; i < idx.count; i++) indices.push(idx.getX(i) + offset);
    else for (let i = 0; i < p.count; i++) indices.push(i + offset);
    offset += p.count;
    g.dispose();
  }
  merged.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  if (normals.length) merged.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
  if (uvs.length) merged.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  merged.setIndex(indices);
  merged.computeBoundingSphere();
  return merged;
}

import { clamp, formatTime } from '../core/noise.js';

const $ = (id) => document.getElementById(id);

export class HUD {
  constructor(world, engine, save) {
    this.world = world;
    this.engine = engine;
    this.save = save;
    this.el = $('hud');
    this.speedCanvas = $('speedo');
    this.minimap = $('minimap');
    this.ctxSpeed = this.speedCanvas.getContext('2d');
    this.ctxMap = this.minimap.getContext('2d');
    this._speedKey = '';
    this._mapKey = '';
    this._mapTimer = 0;
    this._countdownValue = null;
    this.countdownEl = document.createElement('div');
    this.countdownEl.className = 'race-countdown';
    this.el.appendChild(this.countdownEl);
    this.collectTotal = world.collectibles.length || 24;
    const totalSmall = document.querySelector('#collect-count + small');
    if (totalSmall) totalSmall.textContent = '/ ' + this.collectTotal;
  }

  show(on) {
    this.el.classList.toggle('active', on);
  }

  setInteraction(show, title = '', sub = '') {
    const el = $('interaction');
    if (!el) return;
    el.classList.toggle('show', show);
    if (show) { $('interaction-title').textContent = title; $('interaction-sub').textContent = sub; }
  }

  setRacePrompt(show, title = '', sub = '') {
    const el = $('race-enter');
    if (!el) return;
    el.classList.toggle('show', show);
    if (show) { $('race-enter-title').textContent = title; el.querySelector('small').textContent = sub; }
  }

  update(dt, player, race) {
    this.updateWorldInfo(player);
    if (player) this.drawSpeedo(player);
    this._mapTimer += dt;
    if (this._mapTimer > 0.06) { this._mapTimer = 0; this.drawMinimap(player, race); }
    this.updateRace(race, player);
  }

  updateWorldInfo(player) {
    if (!player) return;
    const region = this.world.regionAt(player.pos.x, player.pos.z);
    if (region !== this._region) {
      this._region = region;
      $('region-name').textContent = region;
      $('minimap-region').textContent = region.toUpperCase();
    }
    const hour = this.engine.hour;
    const hh = Math.floor(hour);
    const mm = Math.floor((hour - hh) * 60);
    const time = `${String(hh).padStart(2, '0')}:${String(mm).padStart(2, '0')}`;
    if (time !== this._time) { this._time = time; $('time-of-day').textContent = time; }
    const weather = this.engine.weather === 'rain' ? 'RAIN' : 'CLEAR';
    if (weather !== this._weather) { this._weather = weather; $('weather-label').textContent = weather; }
    const collected = this.world.collectibles.filter(c => c.userData.collected).length;
    if (collected !== this._collected) {
      this._collected = collected;
      $('collect-count').textContent = collected;
    }
    const carName = player.vehicle.name;
    if (carName !== this._carName) {
      this._carName = carName;
      $('hud-car-name').textContent = carName;
      $('hud-car-class').textContent = player.vehicle.category.toUpperCase();
    }
  }

  updateRace(race, player) {
    const hud = $('race-hud');
    if (!race || race.state === 'idle' || !race.event || race.state === 'finished') {
      hud.classList.remove('show');
      this.countdownEl.classList.remove('show');
      this._countdownValue = null;
      return;
    }
    const info = race.getHud();
    if (!info) return;
    hud.classList.add('show');
    $('race-label').textContent = info.label;
    $('race-timer').textContent = formatTime(info.state === 'racing' ? info.time : 0);
    $('race-cp').textContent = info.state === 'countdown' ? 'GET READY' :
      (info.cp >= info.total ? 'FINAL GATE' : `CHECKPOINT ${info.cp} / ${info.total}`);
    $('race-dist').textContent = info.distance > 999 ? (info.distance / 1000).toFixed(2) + ' km' : Math.round(info.distance) + ' m';
    $('race-progress').style.width = (info.progress * 100).toFixed(1) + '%';

    let label = null;
    if (info.state === 'countdown') label = info.countdown > 0.35 ? String(Math.ceil(info.countdown)) : 'GO';
    if (label !== this._countdownValue) {
      this._countdownValue = label;
      if (label) {
        this.countdownEl.textContent = label;
        this.countdownEl.classList.add('show');
        this.countdownEl.classList.toggle('go', label === 'GO');
      } else {
        this.countdownEl.classList.remove('show');
      }
    }
  }

  drawSpeedo(player) {
    const c = this.speedCanvas;
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const w = c.clientWidth || 220;
    const h = c.clientHeight || 220;
    if (c.width !== Math.round(w * dpr) || c.height !== Math.round(h * dpr)) {
      c.width = Math.round(w * dpr);
      c.height = Math.round(h * dpr);
    }
    const ctx = this.ctxSpeed;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);
    const cx = w / 2, cy = h / 2 + h * 0.03;
    const r = Math.min(w, h) * 0.41;
    const start = Math.PI * 0.75;
    const end = Math.PI * 2.25;
    const sweep = end - start;
    const speed = clamp(player.speedKmh, 0, 400);
    const top = 400;
    const frac = speed / top;

    // glass disc
    const disc = ctx.createRadialGradient(cx, cy - r * 0.2, r * 0.1, cx, cy, r * 1.2);
    disc.addColorStop(0, 'rgba(18,25,31,.82)');
    disc.addColorStop(1, 'rgba(6,9,12,.7)');
    ctx.fillStyle = disc;
    ctx.beginPath(); ctx.arc(cx, cy, r * 1.16, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,255,.11)';
    ctx.lineWidth = 1;
    ctx.stroke();

    // ticks
    ctx.save();
    ctx.translate(cx, cy);
    for (let s = 0; s <= top; s += 20) {
      const a = start + (s / top) * sweep;
      const major = s % 100 === 0;
      const inner = r * (major ? 0.80 : 0.87);
      const outer = r * 0.94;
      ctx.beginPath();
      ctx.moveTo(Math.cos(a) * inner, Math.sin(a) * inner);
      ctx.lineTo(Math.cos(a) * outer, Math.sin(a) * outer);
      ctx.strokeStyle = s <= 200 ? 'rgba(230,238,242,.55)' : 'rgba(255,120,70,.62)';
      ctx.lineWidth = major ? 1.8 : 0.9;
      ctx.stroke();
      if (major) {
        ctx.fillStyle = 'rgba(210,220,226,.55)';
        ctx.font = '600 8px "Chakra Petch", sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(String(s), Math.cos(a) * r * 0.69, Math.sin(a) * r * 0.69);
      }
    }
    ctx.restore();

    // active arc
    const grad = ctx.createLinearGradient(cx - r, cy, cx + r, cy);
    grad.addColorStop(0, '#ffb648');
    grad.addColorStop(0.55, '#ff5a12');
    grad.addColorStop(1, '#35e6ff');
    ctx.beginPath();
    ctx.arc(cx, cy, r * 0.985, start, start + sweep * clamp(frac, 0.001, 1));
    ctx.strokeStyle = grad;
    ctx.lineWidth = 3.4;
    ctx.lineCap = 'round';
    ctx.shadowColor = '#ff5a12';
    ctx.shadowBlur = 14;
    ctx.stroke();
    ctx.shadowBlur = 0;

    // needle
    const angle = start + sweep * frac;
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(angle);
    ctx.beginPath();
    ctx.moveTo(-r * 0.12, -2);
    ctx.lineTo(r * 0.72, 0);
    ctx.lineTo(-r * 0.12, 2);
    ctx.closePath();
    ctx.fillStyle = '#ff7a30';
    ctx.shadowColor = '#ff5a12';
    ctx.shadowBlur = 10;
    ctx.fill();
    ctx.restore();

    // hub
    ctx.beginPath(); ctx.arc(cx, cy, 5, 0, Math.PI * 2);
    ctx.fillStyle = '#0b0f13'; ctx.fill();
    ctx.strokeStyle = '#ff7a30'; ctx.lineWidth = 1.4; ctx.stroke();

    // digits
    ctx.textAlign = 'center';
    ctx.fillStyle = '#f4f7f8';
    ctx.font = '700 30px "Chakra Petch", sans-serif';
    ctx.fillText(String(Math.round(speed)), cx, cy + r * 0.40);
    ctx.fillStyle = 'rgba(190,201,208,.75)';
    ctx.font = '600 7px "Chakra Petch", sans-serif';
    ctx.fillText('KM/H', cx, cy + r * 0.56);

    // gear + rpm
    ctx.fillStyle = '#ff5a12';
    ctx.font = '700 13px "Chakra Petch", sans-serif';
    ctx.fillText(player.vehicle.gears > 1 ? String(player.gear) : 'D', cx, cy + r * 0.85);
    ctx.fillStyle = 'rgba(255,255,255,.35)';
    ctx.font = '500 6px "Chakra Petch", sans-serif';
    ctx.fillText('GEAR', cx, cy + r * 0.98);
    const rpmFrac = clamp((player.rpm - 800) / 7200, 0, 1);
    const bw = r * 1.14;
    ctx.fillStyle = 'rgba(255,255,255,.1)';
    ctx.fillRect(cx - bw / 2, cy + r * 0.68, bw, 2);
    ctx.fillStyle = rpmFrac > 0.86 ? '#ff3b2f' : '#35e6ff';
    ctx.fillRect(cx - bw / 2, cy + r * 0.68, bw * rpmFrac, 2);
  }

  drawMinimap(player, race) {
    const c = this.minimap;
    if (!player || !this.world.mapCanvas) return;
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const w = c.clientWidth || 170, h = c.clientHeight || 170;
    if (c.width !== Math.round(w * dpr) || c.height !== Math.round(h * dpr)) {
      c.width = Math.round(w * dpr); c.height = Math.round(h * dpr);
    }
    const ctx = this.ctxMap;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);
    ctx.save();
    ctx.beginPath(); ctx.arc(w / 2, h / 2, Math.min(w, h) / 2, 0, Math.PI * 2); ctx.clip();

    const half = this.world.half;
    const span = 1700;
    const scale = this.world.mapCanvas.width / (half * 2);
    const sx = (player.pos.x + half) * scale - (span / 2) * scale;
    const sy = (player.pos.z + half) * scale - (span / 2) * scale;
    const sw = span * scale;
    ctx.fillStyle = '#14262c';
    ctx.fillRect(0, 0, w, h);
    try {
      ctx.drawImage(this.world.mapCanvas, sx, sy, sw, sw, 0, 0, w, h);
    } catch (_) { /* map not ready */ }

    const toX = x => ((x - player.pos.x) / span + 0.5) * w;
    const toY = z => ((z - player.pos.z) / span + 0.5) * h;
    // event gates
    for (const e of this.world.events) {
      const x = toX(e.start.x), y = toY(e.start.z);
      if (x < 0 || x > w || y < 0 || y > h) continue;
      ctx.beginPath(); ctx.arc(x, y, 3.2, 0, Math.PI * 2);
      ctx.fillStyle = '#ff5a12'; ctx.fill();
      ctx.strokeStyle = 'rgba(255,90,18,.4)'; ctx.lineWidth = 3; ctx.stroke();
    }
    // collectibles
    for (const col of this.world.collectibles) {
      if (col.userData.collected) continue;
      const x = toX(col.position.x), y = toY(col.position.z);
      if (x < 0 || x > w || y < 0 || y > h) continue;
      ctx.beginPath(); ctx.arc(x, y, 2.1, 0, Math.PI * 2);
      ctx.fillStyle = '#ffb648'; ctx.fill();
    }
    // next race checkpoint
    if (race && race.state === 'racing' && race.event) {
      const p = race.event.points[race.cpIndex];
      if (p) {
        const x = toX(p.x), y = toY(p.z);
        if (x > 0 && x < w && y > 0 && y < h) {
          ctx.beginPath(); ctx.arc(x, y, 4, 0, Math.PI * 2);
          ctx.strokeStyle = '#35e6ff'; ctx.lineWidth = 2; ctx.stroke();
        }
      }
    }

    // player arrow
    ctx.save();
    ctx.translate(w / 2, h / 2);
    ctx.rotate(Math.PI - player.heading);
    ctx.beginPath();
    ctx.moveTo(0, -7);
    ctx.lineTo(5, 6);
    ctx.lineTo(0, 3.2);
    ctx.lineTo(-5, 6);
    ctx.closePath();
    ctx.fillStyle = '#35e6ff';
    ctx.shadowColor = '#35e6ff';
    ctx.shadowBlur = 8;
    ctx.fill();
    ctx.restore();
    ctx.restore();

    // ring
    ctx.beginPath(); ctx.arc(w / 2, h / 2, Math.min(w, h) / 2 - 1, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(255,255,255,.08)'; ctx.lineWidth = 1; ctx.stroke();
  }

  toast(text, type = '', icon = 'star') {
    const wrap = $('toasts');
    if (!wrap) return;
    while (wrap.children.length > 3) wrap.firstChild.remove();
    const el = document.createElement('div');
    el.className = 'toast ' + type;
    el.innerHTML = `<svg><use href="#i-${icon}"/></svg><div>${text}</div>`;
    wrap.appendChild(el);
    requestAnimationFrame(() => el.classList.add('show'));
    setTimeout(() => {
      el.classList.remove('show');
      setTimeout(() => el.remove(), 350);
    }, 3400);
  }
}

import { clamp, formatTime } from '../core/noise.js';

const $ = id => document.getElementById(id);

export class WorldMapUI {
  constructor(world, save, callbacks = {}) {
    this.world = world;
    this.save = save;
    this.callbacks = callbacks;
    this.canvas = $('worldmap');
    this.stage = this.canvas.parentElement;
    this.ctx = this.canvas.getContext('2d');
    this.active = false;
    this.zoom = 1.8;
    this.center = { x: 0, z: 0 };
    this.pan = { x: 0, y: 0 };
    this.destination = null;
    this.pointer = null;
    this._bind();
    this._buildEvents();
    this._resize();
  }

  _bind() {
    const c = this.canvas;
    c.addEventListener('pointerdown', (e) => {
      this.pointer = {
        id: e.pointerId, sx: e.clientX, sy: e.clientY,
        px: this.pan.x, py: this.pan.y, moved: false,
      };
      c.setPointerCapture(e.pointerId);
    });
    c.addEventListener('pointermove', (e) => {
      if (this.pointer && this.pointer.id === e.pointerId) {
        const dx = e.clientX - this.pointer.sx, dy = e.clientY - this.pointer.sy;
        if (Math.abs(dx) + Math.abs(dy) > 4) this.pointer.moved = true;
        if (this.pointer.moved) {
          this.pan.x = this.pointer.px + dx;
          this.pan.y = this.pointer.py + dy;
          this._clampPan();
        }
      }
      this._hover(e);
    });
    const up = (e) => {
      if (!this.pointer || this.pointer.id !== e.pointerId) return;
      const moved = this.pointer.moved;
      this.pointer = null;
      if (!moved) this._selectAt(e);
    };
    c.addEventListener('pointerup', up);
    c.addEventListener('pointercancel', () => { this.pointer = null; });
    c.addEventListener('wheel', (e) => {
      e.preventDefault();
      this._zoomAt(e.clientX, e.clientY, e.deltaY < 0 ? 1.15 : 0.87);
    }, { passive: false });
    $('map-zoom-in').addEventListener('click', () => this._zoomAt(this.canvas.clientWidth / 2, this.canvas.clientHeight / 2, 1.32));
    $('map-zoom-out').addEventListener('click', () => this._zoomAt(this.canvas.clientWidth / 2, this.canvas.clientHeight / 2, 0.76));
    $('map-reset').addEventListener('click', () => {
      this.zoom = 1.8;
      this.center = this._playerCenter();
      this.pan = { x: 0, y: 0 };
    });
    $('map-travel-btn').addEventListener('click', () => {
      if (!this.destination) return;
      if (this.callbacks.onTravel) this.callbacks.onTravel(this.destination.x, this.destination.z, this.destination.name);
    });
  }

  _buildEvents() {
    const wrap = $('map-events');
    if (!wrap) return;
    wrap.innerHTML = '';
    for (const e of this.world.events) {
      const best = this.save.bestTimes?.[e.id];
      const row = document.createElement('button');
      row.className = 'map-event';
      row.innerHTML = `<span class="ev-ico"><svg><use href="#i-flag"/></svg></span>
        <div><b>${e.name}</b><small>${e.cps} checkpoints · ${e.roadRef?.name || 'Island route'}</small></div>
        <span class="ev-best">${best ? `<b>${formatTime(best)}</b>` : '<b>—</b>'}<br>BEST</span>`;
      row.addEventListener('click', () => {
        if (this.callbacks.onEvent) this.callbacks.onEvent(e);
      });
      wrap.appendChild(row);
    }
  }

  refresh() {
    this._buildEvents();
    this._updateSide();
  }

  _playerCenter() {
    const p = this.callbacks.getPlayer?.();
    return p ? { x: p.x, z: p.z } : { x: -1500, z: 640 };
  }

  open() {
    this.active = true;
    this.zoom = Math.max(1.55, this.zoom);
    this.center = this._playerCenter();
    this.pan = { x: 0, y: 0 };
    this._resize();
    this.refresh();
    this.draw();
  }
  close() { this.active = false; this.pointer = null; }

  _resize() {
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const w = this.stage.clientWidth || window.innerWidth;
    const h = this.stage.clientHeight || window.innerHeight;
    if (this.canvas.width !== Math.round(w * dpr) || this.canvas.height !== Math.round(h * dpr)) {
      this.canvas.width = Math.round(w * dpr);
      this.canvas.height = Math.round(h * dpr);
    }
    this.w = w; this.h = h; this.dpr = dpr;
    this.fit = Math.min(w, h) * 0.93 / this.world.size;
  }

  get viewScale() { return this.fit * this.zoom; }

  _clampPan() {
    const maxX = Math.max(0, this.w * 0.45);
    const maxY = Math.max(0, this.h * 0.45);
    this.pan.x = clamp(this.pan.x, -maxX, maxX);
    this.pan.y = clamp(this.pan.y, -maxY, maxY);
    const worldSpan = this.w / this.viewScale;
    this.center.x = clamp(this.center.x, -this.world.half + worldSpan * 0.1, this.world.half - worldSpan * 0.1);
  }

  _zoomAt(sx, sy, factor) {
    const before = this._toWorld(sx, sy);
    this.zoom = clamp(this.zoom * factor, 0.8, 7);
    const after = this._toWorld(sx, sy);
    this.center.x += before.x - after.x;
    this.center.z += before.z - after.z;
    this._clampPan();
    this.draw();
  }

  _toWorld(sx, sy) {
    const r = this.canvas.getBoundingClientRect();
    const x = sx - r.left, y = sy - r.top;
    return {
      x: this.center.x + (x - this.w / 2 - this.pan.x) / this.viewScale,
      z: this.center.z + (y - this.h / 2 - this.pan.y) / this.viewScale,
    };
  }

  _toScreen(x, z) {
    return {
      x: this.w / 2 + (x - this.center.x) * this.viewScale + this.pan.x,
      y: this.h / 2 + (z - this.center.z) * this.viewScale + this.pan.y,
    };
  }

  _hover(e) {
    if (!this.active) return;
    const p = this._toWorld(e.clientX, e.clientY);
    let label = this.world.regionAt(p.x, p.z);
    for (const ev of this.world.events) {
      const s = this._toScreen(ev.start.x, ev.start.z);
      if (Math.hypot(s.x - (e.clientX - this.canvas.getBoundingClientRect().left), s.y - (e.clientY - this.canvas.getBoundingClientRect().top)) < 16) {
        label = ev.name; break;
      }
    }
    const tip = $('map-tooltip');
    const r = this.canvas.getBoundingClientRect();
    tip.textContent = label;
    tip.style.left = (e.clientX - r.left) + 'px';
    tip.style.top = (e.clientY - r.top) + 'px';
    tip.classList.add('show');
    $('map-coords').textContent = `X ${p.x.toFixed(0)} · Z ${p.z.toFixed(0)}`;
    $('map-region-name').textContent = label;
    $('map-coords').dataset.x = p.x;
    $('map-coords').dataset.z = p.z;
  }

  _selectAt(e) {
    const p = this._toWorld(e.clientX, e.clientY);
    // snap to an event start when clicking close to its marker
    let dest = { x: p.x, z: p.z, name: this.world.regionAt(p.x, p.z) };
    for (const ev of this.world.events) {
      const s = this._toScreen(ev.start.x, ev.start.z);
      const r = this.canvas.getBoundingClientRect();
      if (Math.hypot(s.x - (e.clientX - r.left), s.y - (e.clientY - r.top)) < 17) {
        dest = { x: ev.start.x, z: ev.start.z, name: ev.name };
        break;
      }
    }
    this.destination = dest;
    this._updateSide();
    this.draw();
  }

  _updateSide() {
    const name = $('travel-name'), coords = $('travel-coords');
    if (!name) return;
    if (this.destination) {
      name.textContent = this.destination.name;
      coords.textContent = `X ${this.destination.x.toFixed(0)} · Z ${this.destination.z.toFixed(0)}`;
    } else {
      name.textContent = 'Tap the map';
      coords.textContent = '—';
    }
    const collected = this.world.collectibles.filter(c => c.userData.collected).length;
    $('map-collect').textContent = `${collected} / ${this.world.collectibles.length}`;
    $('map-collect-bar').style.width = (collected / Math.max(1, this.world.collectibles.length) * 100) + '%';
  }

  draw() {
    if (!this.active) return;
    const ctx = this.ctx;
    const w = this.w, h = this.h;
    if (!w || !h) return;
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = '#081014';
    ctx.fillRect(0, 0, w, h);

    const scale = this.viewScale;
    const dw = this.world.size * scale;
    const dx = w / 2 + this.pan.x - (this.center.x + this.world.half) * scale;
    const dy = h / 2 + this.pan.y - (this.center.z + this.world.half) * scale;
    ctx.imageSmoothingEnabled = true;
    ctx.drawImage(this.world.mapCanvas, dx, dy, dw, dw);

    // faint longitude / latitude grid
    ctx.strokeStyle = 'rgba(180,210,225,.055)';
    ctx.lineWidth = 1;
    const grid = 1000 * scale;
    const gx = ((dx % grid) + grid) % grid;
    const gy = ((dy % grid) + grid) % grid;
    for (let x = gx; x < w; x += grid) { ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke(); }
    for (let y = gy; y < h; y += grid) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke(); }

    // events
    for (const ev of this.world.events) {
      const s = this._toScreen(ev.start.x, ev.start.z);
      if (s.x < -30 || s.x > w + 30 || s.y < -30 || s.y > h + 30) continue;
      ctx.beginPath();
      ctx.arc(s.x, s.y, 7, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,90,18,.16)';
      ctx.fill();
      ctx.strokeStyle = 'rgba(255,90,18,.4)';
      ctx.lineWidth = 1.4; ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(s.x, s.y - 5); ctx.lineTo(s.x + 5, s.y); ctx.lineTo(s.x, s.y + 5); ctx.lineTo(s.x - 5, s.y); ctx.closePath();
      ctx.fillStyle = '#ff5a12'; ctx.shadowColor = '#ff5a12'; ctx.shadowBlur = 10; ctx.fill(); ctx.shadowBlur = 0;
    }

    // collectibles
    for (const col of this.world.collectibles) {
      if (col.userData.collected) continue;
      const s = this._toScreen(col.position.x, col.position.z);
      if (s.x < 0 || s.x > w || s.y < 0 || s.y > h) continue;
      ctx.beginPath(); ctx.arc(s.x, s.y, 2.3, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,182,72,.85)'; ctx.fill();
    }

    // destination
    if (this.destination) {
      const s = this._toScreen(this.destination.x, this.destination.z);
      ctx.beginPath(); ctx.arc(s.x, s.y, 6, 0, Math.PI * 2);
      ctx.fillStyle = '#35e6ff'; ctx.shadowColor = '#35e6ff'; ctx.shadowBlur = 16; ctx.fill(); ctx.shadowBlur = 0;
      ctx.beginPath(); ctx.arc(s.x, s.y, 13, 0, Math.PI * 2);
      ctx.strokeStyle = 'rgba(53,230,255,.35)'; ctx.lineWidth = 1; ctx.stroke();
    }

    // player
    const pl = this.callbacks.getPlayer?.();
    if (pl) {
      const s = this._toScreen(pl.x, pl.z);
      ctx.save();
      ctx.translate(s.x, s.y);
      ctx.rotate(Math.PI - (pl.heading || 0));
      ctx.beginPath(); ctx.moveTo(0, -9); ctx.lineTo(6, 8); ctx.lineTo(0, 4); ctx.lineTo(-6, 8); ctx.closePath();
      ctx.fillStyle = '#35e6ff'; ctx.shadowColor = '#35e6ff'; ctx.shadowBlur = 14; ctx.fill();
      ctx.restore();
      ctx.beginPath(); ctx.arc(s.x, s.y, 17, 0, Math.PI * 2);
      ctx.strokeStyle = 'rgba(53,230,255,.22)'; ctx.stroke();
    }

    // corner labels
    ctx.fillStyle = 'rgba(180,200,210,.35)';
    ctx.font = '600 8px "Chakra Petch", sans-serif';
    ctx.textAlign = 'left';
    if (this.destination) {
      ctx.fillStyle = 'rgba(200,215,222,.6)';
      ctx.fillText('HOLD AND DRAG TO PAN · SCROLL TO ZOOM', 16, 18);
    }
  }
}

import * as THREE from 'three';
import { createCarModel } from '../vehicles/carModel.js';
import { CATEGORIES, PAINT_COLORS, RIM_STYLES, RIM_COLORS, getVehicle, vehiclePerformance } from '../vehicles/vehicles.js';
import { clamp, formatNumber } from '../core/noise.js';

const $ = id => document.getElementById(id);
const ACCENTS = [0x111417, 0xff5a12, 0x35e6ff, 0xf2f0e4, 0xffb648, 0xc41d22, 0x22c7d8, 0x8a9095];
const UPGRADE_BASE = { engine: 18000, brakes: 12000, suspension: 15000, turbo: 20000 };

export class GarageUI {
  constructor(engine, save, callbacks = {}) {
    this.engine = engine;
    this.save = save;
    this.callbacks = callbacks;
    this.el = $('garage');
    this.active = false;
    this.filter = 'All';
    this.selectedId = null;
    this.drag = null;
    this.autoRotate = true;
    this.zoom = 1;
    this.turntableAngle = 0;
    this._buildScene();
    this._bind();
    this._buildFilters();
    this._buildSwatches();
    this._buildRims();
  }

  _buildScene() {
    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(0x05070a);
    this.scene.environment = this.engine.envSunset;
    this.scene.environmentIntensity = 1.1;
    this.scene.fog = new THREE.Fog(0x05070a, 18, 46);
    this.camera = new THREE.PerspectiveCamera(38, window.innerWidth / window.innerHeight, 0.1, 120);
    this.camera.position.set(4.6, 2.8, 7.2);
    this.camera.lookAt(0, 0.9, 0);

    // backdrop gradient
    const bg = new THREE.Mesh(
      new THREE.SphereGeometry(48, 32, 20),
      new THREE.ShaderMaterial({
        side: THREE.BackSide, depthWrite: false, fog: false,
        vertexShader: 'varying vec3 vP; void main(){ vP = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }',
        fragmentShader: `varying vec3 vP; void main(){
          float h = normalize(vP).y;
          vec3 top = vec3(.010,.016,.023);
          vec3 mid = vec3(.037,.053,.066);
          vec3 low = vec3(.008,.011,.014);
          vec3 c = mix(low, mid, smoothstep(-.35,.12,h));
          c = mix(c, top, smoothstep(.12,.7,h));
          float glow = exp(-abs(h-.02)*20.0);
          c += vec3(.10,.035,.008) * glow * .55;
          gl_FragColor = vec4(c,1.0);
        }`,
      }),
    );
    this.scene.add(bg);

    const floorMat = new THREE.MeshStandardMaterial({ color: 0x0c1115, roughness: 0.3, metalness: 0.62, envMapIntensity: 1.2 });
    const floor = new THREE.Mesh(new THREE.CircleGeometry(16, 72), floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    this.scene.add(floor);

    const grid = new THREE.GridHelper(30, 30, 0x27323b, 0x141b21);
    grid.position.y = 0.012;
    grid.material.transparent = true;
    grid.material.opacity = 0.35;
    this.scene.add(grid);

    // lit turntable
    this.turntable = new THREE.Group();
    this.scene.add(this.turntable);
    const platform = new THREE.Mesh(
      new THREE.CylinderGeometry(3.35, 3.55, 0.12, 72),
      new THREE.MeshStandardMaterial({ color: 0x141b20, roughness: 0.24, metalness: 0.8 }),
    );
    platform.position.y = 0.06;
    platform.receiveShadow = true;
    this.turntable.add(platform);
    const plinthRing = new THREE.Mesh(
      new THREE.TorusGeometry(3.38, 0.025, 6, 96),
      new THREE.MeshStandardMaterial({ color: 0xff5a12, emissive: 0xff4a00, emissiveIntensity: 2.4 }),
    );
    plinthRing.rotation.x = Math.PI / 2;
    plinthRing.position.y = 0.13;
    this.turntable.add(plinthRing);
    const plinthRing2 = new THREE.Mesh(
      new THREE.TorusGeometry(2.1, 0.012, 5, 80),
      new THREE.MeshStandardMaterial({ color: 0x35e6ff, emissive: 0x35e6ff, emissiveIntensity: 1.8 }),
    );
    plinthRing2.rotation.x = Math.PI / 2;
    plinthRing2.position.y = 0.132;
    this.turntable.add(plinthRing2);
    this.carHolder = new THREE.Group();
    this.turntable.add(this.carHolder);

    this.scene.add(new THREE.HemisphereLight(0x9db7c9, 0x1b1511, 0.9));
    const key = new THREE.SpotLight(0xfff0df, 130, 26, 0.62, 0.55, 1.5);
    key.position.set(-3.5, 8.5, 5.2);
    key.target.position.set(0, 0.6, 0);
    key.castShadow = true;
    key.shadow.mapSize.set(1024, 1024);
    key.shadow.bias = -0.0008;
    this.scene.add(key, key.target);
    const fill = new THREE.PointLight(0x35e6ff, 28, 20, 1.6);
    fill.position.set(6, 2.2, -3.2);
    this.scene.add(fill);
    const rim = new THREE.SpotLight(0xff5a12, 120, 24, 0.55, 0.6, 1.4);
    rim.position.set(4.5, 4.5, -6);
    rim.target.position.set(0, 1, 0);
    this.scene.add(rim, rim.target);
    const front = new THREE.PointLight(0xffd9b0, 20, 18, 1.5);
    front.position.set(0, 1.3, 7);
    this.scene.add(front);

    // vertical light bars
    for (const s of [-1, 1]) {
      const bar = new THREE.Mesh(
        new THREE.BoxGeometry(0.06, 4.6, 0.06),
        new THREE.MeshStandardMaterial({ color: s < 0 ? 0xff5a12 : 0x35e6ff, emissive: s < 0 ? 0xff4a00 : 0x35e6ff, emissiveIntensity: 2.4 }),
      );
      bar.position.set(s * 8.4, 2.3, -7.5);
      this.scene.add(bar);
    }
  }

  _bind() {
    $('garage-back').addEventListener('click', () => { if (this.callbacks.onExit) this.callbacks.onExit(); });
    this.el.addEventListener('pointerdown', (e) => {
      if (e.target !== this.el) return;
      this.drag = { x: e.clientX, id: e.pointerId, angle: this.turntableAngle };
      this.autoRotate = false;
      try { this.el.setPointerCapture(e.pointerId); } catch (_) { /* noop */ }
    });
    this.el.addEventListener('pointermove', (e) => {
      if (!this.drag || this.drag.id !== e.pointerId) return;
      this.turntableAngle = this.drag.angle + (e.clientX - this.drag.x) * 0.009;
    });
    const end = () => { this.drag = null; };
    this.el.addEventListener('pointerup', end);
    this.el.addEventListener('pointercancel', end);
    this.el.addEventListener('dblclick', (e) => {
      if (e.target !== this.el) return;
      this.turntableAngle = 0;
      this.zoom = 1;
      this.autoRotate = true;
    });
    this.el.addEventListener('wheel', (e) => {
      if (e.target.closest('.garage-left,.garage-right')) return;
      e.preventDefault();
      this.zoom = clamp(this.zoom + (e.deltaY > 0 ? 0.08 : -0.08), 0.62, 1.6);
    }, { passive: false });
    window.addEventListener('resize', () => {
      this.camera.aspect = window.innerWidth / window.innerHeight;
      this.camera.updateProjectionMatrix();
    });
    $('garage-select').addEventListener('click', () => {
      if (this._owned(this.selectedId)) {
        if (this.callbacks.onDrive) this.callbacks.onDrive(this.selectedId);
      } else if (this._buy(this.selectedId)) {
        if (this.callbacks.onDrive) this.callbacks.onDrive(this.selectedId);
      }
    });
    $('garage-buy').addEventListener('click', () => this._buy(this.selectedId));
    $('garage-fav').addEventListener('click', () => this._toggleFav());
    document.querySelectorAll('.custom-tabs button').forEach(btn => {
      btn.addEventListener('click', () => {
        document.querySelectorAll('.custom-tabs button').forEach(b => b.classList.toggle('active', b === btn));
        document.querySelectorAll('.custom-panel').forEach(p => p.classList.toggle('active', p.dataset.panel === btn.dataset.tab));
      });
    });
    $('ride-height').addEventListener('input', (e) => {
      const l = this._loadout(this.selectedId);
      l.rideHeight = Number(e.target.value);
      $('ride-height-val').textContent = l.rideHeight;
      if (this.model) this.model.setRideHeight(l.rideHeight);
      this._saveLoadout();
    });
    $('camber').addEventListener('input', (e) => {
      const l = this._loadout(this.selectedId);
      l.camber = Number(e.target.value);
      $('camber-val').textContent = l.camber;
      if (this.model) {
        const rad = l.camber * Math.PI / 180;
        this.model.wheels.forEach(w => { w.camber = rad; w.steerRoot.rotation.z = rad; });
      }
      this._saveLoadout();
    });
    document.querySelectorAll('.up-btn').forEach(btn => btn.addEventListener('click', () => {
      const type = btn.id.replace('up-', '').replace('-btn', '').replace('susp', 'suspension');
      this._upgrade(type);
    }));
    document.querySelectorAll('#paint-finishes button').forEach(btn => {
      btn.addEventListener('click', () => {
        const l = this._loadout(this.selectedId);
        l.finish = btn.dataset.finish;
        document.querySelectorAll('#paint-finishes button').forEach(b => b.classList.toggle('active', b === btn));
        if (this.model) this.model.setPaint(l.paint, l.finish);
        this._saveLoadout();
      });
    });
  }

  _buildFilters() {
    const wrap = $('garage-filters');
    wrap.innerHTML = '';
    for (const c of CATEGORIES) {
      const b = document.createElement('button');
      b.textContent = c.toUpperCase();
      b.dataset.cat = c;
      b.classList.toggle('active', c === this.filter);
      b.addEventListener('click', () => {
        this.filter = c;
        wrap.querySelectorAll('button').forEach(x => x.classList.toggle('active', x === b));
        this._renderList();
      });
      wrap.appendChild(b);
    }
  }

  _buildSwatches() {
    const wrap = $('paint-swatches');
    wrap.innerHTML = '';
    PAINT_COLORS.forEach((p) => {
      const b = document.createElement('button');
      b.className = 'swatch';
      b.style.background = '#' + p.hex.toString(16).padStart(6, '0');
      b.title = p.name;
      b.dataset.hex = p.hex;
      b.addEventListener('click', () => {
        const l = this._loadout(this.selectedId);
        l.paint = p.hex;
        l.finish = p.finish;
        if (this.model) this.model.setPaint(p.hex, p.finish);
        $('paint-name').textContent = p.name;
        document.querySelectorAll('#paint-swatches .swatch').forEach(x => x.classList.toggle('active', x === b));
        document.querySelectorAll('#paint-finishes button').forEach(x => x.classList.toggle('active', x.dataset.finish === p.finish));
        this._saveLoadout();
      });
      wrap.appendChild(b);
    });
    const accents = $('paint-accents');
    accents.innerHTML = '';
    ACCENTS.forEach((hex) => {
      const b = document.createElement('button');
      b.style.background = '#' + hex.toString(16).padStart(6, '0');
      b.dataset.hex = hex;
      b.addEventListener('click', () => {
        const l = this._loadout(this.selectedId);
        l.accent = hex;
        if (this.model) this.model.setAccent(hex);
        accents.querySelectorAll('button').forEach(x => x.classList.toggle('active', x === b));
        this._saveLoadout();
      });
      accents.appendChild(b);
    });
    const rimWrap = $('rim-swatches');
    rimWrap.innerHTML = '';
    RIM_COLORS.forEach((c) => {
      const b = document.createElement('button');
      b.className = 'swatch';
      b.style.background = '#' + c.hex.toString(16).padStart(6, '0');
      b.title = c.name;
      b.dataset.hex = c.hex;
      b.addEventListener('click', () => {
        const l = this._loadout(this.selectedId);
        l.rimColor = c.hex;
        if (this.model) this.model.setRimColor(c.hex);
        rimWrap.querySelectorAll('button').forEach(x => x.classList.toggle('active', x === b));
        this._saveLoadout();
      });
      rimWrap.appendChild(b);
    });
  }

  _buildRims() {
    const wrap = $('rim-list');
    wrap.innerHTML = '';
    for (const r of RIM_STYLES) {
      const b = document.createElement('button');
      b.className = 'rim-item';
      b.dataset.rim = r.id;
      b.innerHTML = `<svg><use href="#i-wheel"/></svg><div><b>${r.name.toUpperCase()}</b><small>${r.spokes ? r.spokes + ' SPOKE' : 'DISC'}</small></div>`;
      b.addEventListener('click', () => {
        const l = this._loadout(this.selectedId);
        l.rimStyle = r.id;
        this._saveLoadout();
        this._renderCar();
        this._syncRimList();
      });
      wrap.appendChild(b);
    }
  }

  _owned(id) {
    const v = getVehicle(id);
    return v.price === 0 || this.save.owned.includes(id);
  }

  _loadout(id) {
    const v = getVehicle(id);
    if (!this.save.loadouts) this.save.loadouts = {};
    if (!this.save.loadouts[id]) {
      this.save.loadouts[id] = {
        paint: v.color, finish: v.finish || 'metallic', rimStyle: v.body === 'offroad' || v.body === 'pickup' ? 'offroad' : 'split5',
        rimColor: 0x15171a, accent: undefined, rideHeight: 0, camber: -1,
        upgrades: { engine: 0, brakes: 0, suspension: 0, turbo: 0 },
      };
    }
    const l = this.save.loadouts[id];
    l.upgrades = l.upgrades || { engine: 0, brakes: 0, suspension: 0, turbo: 0 };
    return l;
  }

  _saveLoadout() {
    if (this.callbacks.persist) this.callbacks.persist();
  }

  _upgrade(type) {
    const l = this._loadout(this.selectedId);
    const lvl = l.upgrades[type] || 0;
    if (lvl >= 3) return;
    const cost = Math.round(UPGRADE_BASE[type] * (1 + lvl * 0.8));
    if (this.save.credits < cost) {
      if (this.callbacks.toast) this.callbacks.toast('Not enough credits for that upgrade.', '', 'lock');
      return;
    }
    this.save.credits -= cost;
    l.upgrades[type] = lvl + 1;
    this._saveLoadout();
    if (this.callbacks.audio) this.callbacks.audio.ui();
    if (this.callbacks.toast) this.callbacks.toast(`<b>${type.toUpperCase()}</b> upgraded to stage ${lvl + 1}.`, 'cyan', 'check');
    this._updateMeta();
    this._renderStats(getVehicle(this.selectedId));
  }

  _buy(id) {
    if (this._owned(id)) return true;
    const v = getVehicle(id);
    if (this.save.credits < v.price) {
      if (this.callbacks.toast) this.callbacks.toast(`You need <b>C ${formatNumber(v.price - this.save.credits)}</b> more.`, '', 'lock');
      return false;
    }
    this.save.credits -= v.price;
    this.save.owned.push(id);
    this._saveLoadout();
    if (this.callbacks.audio) this.callbacks.audio.collect();
    if (this.callbacks.toast) this.callbacks.toast(`<b>${v.name}</b> added to your collection.`, 'gold', 'garage');
    this._updateMeta();
    this._renderList();
    this._renderStats(v);
    this._updateButtons();
    return true;
  }

  _toggleFav() {
    const id = this.selectedId;
    const arr = this.save.favourites || (this.save.favourites = []);
    const i = arr.indexOf(id);
    if (i >= 0) arr.splice(i, 1); else arr.push(id);
    this._saveLoadout();
    $('garage-fav').classList.toggle('active', arr.includes(id));
    this._renderList();
  }

  open(preferredId) {
    this.active = true;
    this._resize();
    this.filter = 'All';
    this.el.querySelectorAll('#garage-filters button').forEach(b => b.classList.toggle('active', b.dataset.cat === 'All'));
    this.selectedId = preferredId || this.selectedId || this.save.current;
    this.turntableAngle = -0.55;
    this.autoRotate = true;
    this.zoom = 1;
    this._renderList();
    this._select(preferredId || this.selectedId, false);
    this._updateMeta();
    this.draw(0);
  }

  close() { this.active = false; this.drag = null; }

  _resize() {
    this.camera.aspect = window.innerWidth / window.innerHeight;
    this.camera.updateProjectionMatrix();
  }

  _select(id, rebuild = true) {
    this.selectedId = id;
    if (rebuild) this._renderCar();
    const v = getVehicle(id);
    const l = this._loadout(id);
    $('garage-tag').textContent = v.category.toUpperCase();
    $('garage-car-name').textContent = v.name;
    $('garage-car-sub').textContent = `${v.drivetrain} drive · ${v.gears > 1 ? v.gears + '-speed' : 'single-speed'} · ${v.engine.note}`;
    $('paint-name').textContent = (PAINT_COLORS.find(p => p.hex === l.paint) || PAINT_COLORS[0]).name;
    $('ride-height').value = l.rideHeight;
    $('ride-height-val').textContent = l.rideHeight;
    $('camber').value = l.camber;
    $('camber-val').textContent = l.camber;
    this._renderStats(v);
    this._updateButtons();
    this._syncSwatches();
    this._syncRimList();
    this._syncUpgrades();
    $('garage-fav').classList.toggle('active', (this.save.favourites || []).includes(id));
    const cards = this.el.querySelectorAll('.car-card');
    cards.forEach(c => {
      const active = c.dataset.id === id;
      c.classList.toggle('active', active);
      if (active) c.scrollIntoView({ block: 'nearest' });
    });
  }

  _renderCar() {
    const v = getVehicle(this.selectedId);
    const l = this._loadout(this.selectedId);
    if (this.model) {
      this.carHolder.remove(this.model.root);
      this.model.dispose();
    }
    this.model = createCarModel(v, {
      paint: l.paint, finish: l.finish, rimStyle: l.rimStyle, rimColor: l.rimColor,
      accent: l.accent, camber: l.camber,
    });
    this.model.setRideHeight(l.rideHeight);
    this.model.root.position.y = 0.13;
    this.model.root.traverse(o => { if (o.isMesh) o.castShadow = true; });
    this.carHolder.add(this.model.root);
    const size = this.model.dims.L;
    this.camera.position.set(size * 0.88, 2.35, size * 1.38);
    this.camera.lookAt(0, this.model.dims.H * 0.45, 0);
  }

  _renderList() {
    const wrap = $('garage-cars');
    wrap.innerHTML = '';
    const list = this.save.owned.length ? null : null;
    const vehicles = getVehicle ? this._all() : [];
    for (const v of vehicles) {
      if (this.filter !== 'All' && v.category !== this.filter) continue;
      const owned = this._owned(v.id);
      const b = document.createElement('button');
      b.className = 'car-card' + (v.id === this.selectedId ? ' active' : '');
      b.dataset.id = v.id;
      b.innerHTML = `<span class="car-ico"><svg viewBox="0 0 64 28"><path d="M3 20h3l4-3 8-1 7-8h16l7 8 10 1 4 3h2" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/><circle cx="15" cy="21" r="4" fill="none" stroke="currentColor" stroke-width="1.7"/><circle cx="48" cy="21" r="4" fill="none" stroke="currentColor" stroke-width="1.7"/></svg></span>
        <span class="cc-info"><b>${v.name}</b><small>${v.category} · ${v.grade}</small></span>
        ${(this.save.favourites || []).includes(v.id) ? '<svg class="fav"><use href="#i-star"/></svg>' : ''}
        ${owned ? '<span class="owned-dot"></span>' : '<span class="lock"><svg><use href="#i-lock"/></svg></span>'}`;
      b.addEventListener('click', () => this._select(v.id));
      wrap.appendChild(b);
    }
  }

  _all() {
    return CATEGORIES.includes('All') ? getVehicle ? null : null : null;
  }

  _updateMeta() {
    $('garage-credits').textContent = formatNumber(this.save.credits);
    $('garage-owned').textContent = this.save.owned.length;
    $('menu-credits').textContent = formatNumber(this.save.credits);
    $('menu-owned').textContent = this.save.owned.length;
  }

  _renderStats(v) {
    const l = this._loadout(v.id);
    const perf = vehiclePerformance(v, l.upgrades);
    $('stat-power').textContent = formatNumber(perf.hp);
    $('stat-top').textContent = Math.round(perf.top);
    $('stat-accel').textContent = perf.accel.toFixed(1);
    $('stat-weight').textContent = formatNumber(perf.weight);
    $('bar-accel').style.width = clamp((8.5 - perf.accel) / 6.2 * 100, 4, 100) + '%';
    $('bar-handling').style.width = clamp(perf.handling * 100, 4, 100) + '%';
    $('bar-braking').style.width = clamp(perf.braking * 100, 4, 100) + '%';
    $('bar-drift').style.width = clamp(v.drift * 100, 4, 100) + '%';
    this._updateButtons(perf);
  }

  _updateButtons(perf) {
    const id = this.selectedId;
    const v = getVehicle(id);
    const owned = this._owned(id);
    $('garage-buy').classList.toggle('hidden', owned);
    $('garage-buy-label').textContent = `BUY · C ${formatNumber(v.price)}`;
    $('garage-select').querySelector('span').textContent = owned ? 'SELECT & DRIVE' : 'BUY & DRIVE';
    $('garage-fav').classList.toggle('active', (this.save.favourites || []).includes(id));
  }

  _syncSwatches() {
    const l = this._loadout(this.selectedId);
    document.querySelectorAll('#paint-swatches .swatch').forEach(b => b.classList.toggle('active', Number(b.dataset.hex) === l.paint));
    document.querySelectorAll('#paint-finishes button').forEach(b => b.classList.toggle('active', b.dataset.finish === l.finish));
    document.querySelectorAll('#paint-accents button').forEach(b => b.classList.toggle('active', Number(b.dataset.hex) === l.accent));
    document.querySelectorAll('#rim-swatches .swatch').forEach(b => b.classList.toggle('active', Number(b.dataset.hex) === l.rimColor));
  }

  _syncRimList() {
    const l = this._loadout(this.selectedId);
    document.querySelectorAll('#rim-list .rim-item').forEach(b => b.classList.toggle('active', b.dataset.rim === (l.rimStyle || 'split5')));
  }

  _syncUpgrades() {
    const l = this._loadout(this.selectedId);
    const map = { engine: 'engine', brakes: 'brakes', suspension: 'susp', turbo: 'turbo' };
    for (const [type, short] of Object.entries(map)) {
      const lvl = l.upgrades[type] || 0;
      const label = lvl === 0 ? 'STOCK' : `STAGE ${lvl}`;
      $(`up-${short}-lvl`).textContent = label;
      const btn = $(`up-${short}-btn`);
      if (lvl >= 3) {
        btn.textContent = 'MAXED';
        btn.disabled = true;
      } else {
        const cost = Math.round(UPGRADE_BASE[type] * (1 + lvl * 0.8));
        btn.textContent = `UPGRADE · ${formatNumber(cost)}`;
        btn.disabled = this.save.credits < cost;
      }
    }
  }

  draw(dt = 0) {
    if (!this.active) return;
    if (this.autoRotate && !this.drag) this.turntableAngle += dt * 0.16;
    this.turntable.rotation.y = this.turntableAngle;
    // subtle turntable bob for the showcase
    this.carHolder.position.y = Math.sin(performance.now() * 0.0007) * 0.012;
    const size = this.model ? this.model.dims.L : 4.7;
    const dist = size * 1.38 * this.zoom;
    const height = 2.35 * Math.max(0.85, this.zoom);
    this.camera.position.set(Math.sin(0.62) * dist, height, Math.cos(0.62) * dist);
    this.camera.lookAt(0, (this.model?.dims.H || 1.2) * 0.45, 0);
    this.engine.render(this.scene, this.camera);
  }

  refreshCredits() { this._updateMeta(); this._syncUpgrades(); }
}

