update(dt) {
  if (!this.cars.length) return;
  for (let i = 0; i < this.cars.length; i++) {
    const c = this.cars[i];
    const pts = c.road.points;
    const n = pts.length;
    c.frac += (c.dir * c.speed * dt) / Math.max(1, c.len);
    if (c.road.closed) {
      while (c.frac >= 1) {
        c.frac -= 1;
        c.seg = (c.seg + 1) % n;
      }
      while (c.frac < 0) {
        c.frac += 1;
        c.seg = (c.seg - 1 + n) % n;
      }
    } else {
      // Open roads have n-1 segments. Bounce off the ends instead of
      // wrapping from the last point back to the first.
      while (c.frac >= 1) {
        c.frac -= 1;
        c.seg += 1;
        if (c.seg >= n - 1) {
          c.seg = Math.max(0, n - 2);
          c.frac = 1 - c.frac;
          c.dir = -1;
        }
      }
      while (c.frac < 0) {
        c.frac += 1;
        c.seg -= 1;
        if (c.seg < 0) {
          c.seg = 0;
          c.frac = -c.frac;
          c.dir = 1;
        }
      }
    }
    const a = pts[c.seg % n], b = pts[(c.seg + 1) % n];
    c.len = Math.hypot(b.x - a.x, b.z - a.z) || 1;
    this._place(i);
  }

