import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core/index.mjs';
import fs from 'node:fs';

const url = process.argv[2] || 'http://localhost:3002/?quality=low&v=20';
const tag = process.argv[3] || 'test';
const logs = [];
const browser = await chromium.launch({
  channel: 'chromium',
  headless: false,
  args: ['--enable-gpu', '--ignore-gpu-blocklist', '--enable-unsafe-swiftshader', '--enable-unsafe-webgpu', '--use-angle=vulkan', '--enable-features=Vulkan', '--use-vulkan=swiftshader', '--use-webgpu-adapter=swiftshader', '--disable-vulkan-surface'],
});
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('console', m => logs.push(`[${m.type()}] ${m.text()}`));
page.on('pageerror', e => logs.push(`[pageerror] ${e.stack || e.message}`));
try {
  await page.goto(url, { waitUntil: 'load', timeout: 60000 });
  await page.waitForFunction(() => document.querySelector('#loading')?.classList.contains('done'), null, { timeout: 60000 });
  await page.waitForTimeout(1200);
  console.log('MENU', await page.evaluate(() => ({ title: document.title, pct: document.querySelector('#load-pct')?.textContent, canvas: !!document.querySelector('#gl'), menuVisible: getComputedStyle(document.querySelector('#menu')).display })));
  await page.screenshot({ path: `screenshots/${tag}-menu.png`, timeout: 30000 });
  console.log('menu screenshot done');
  await page.screenshot({ path: `screenshots/${tag}-menu.png`, timeout: 30000 }).catch(e => console.log('menu shot 2 failed', e.message));
  await page.click('#btn-continue', { timeout: 10000 });
  await page.waitForTimeout(2500);
  console.log('DRIVE', await page.evaluate(() => ({ speed: document.querySelector('#speed-value')?.textContent, hud: getComputedStyle(document.querySelector('#hud')).display, gear: document.querySelector('#gear-value')?.textContent, region: document.querySelector('#hud-region')?.textContent })));
  await page.screenshot({ path: `screenshots/${tag}-drive.png`, timeout: 30000 });
  console.log('drive screenshot done');
  await page.keyboard.press('c');
  await page.waitForTimeout(1500);
  await page.screenshot({ path: `screenshots/${tag}-cam.png`, timeout: 30000 });
  console.log('cam screenshot done');
  await page.keyboard.down('w');
  await page.waitForTimeout(3000);
  await page.keyboard.up('w');
  console.log('DEPART', await page.evaluate(() => ({ speed: document.querySelector('#speed-value')?.textContent, gear: document.querySelector('#gear-value')?.textContent, region: document.querySelector('#hud-region')?.textContent })));
  await page.screenshot({ path: `screenshots/${tag}-depart.png`, timeout: 30000 });
  console.log('depart screenshot done');
} catch (e) {
  console.log('FAIL', e.message);
} finally {
  fs.writeFileSync(`/tmp/opencode/${tag}-console.log`, logs.join('\n'));
  console.log('LOGCOUNT', logs.length, 'ERRORS', logs.filter(l => l.startsWith('[error]') || l.startsWith('[pageerror]')).length);
  for (const l of logs.filter(l => l.startsWith('[error]') || l.startsWith('[pageerror]')).slice(0, 20)) console.log(l);
  await browser.close();
}

