297:       }
298:     }
299: 
300:     // world edge
301:     const edge = world.half - 90;
302:     if (Math.abs(this.pos.x) > edge || Math.abs(this.pos.z) > edge) {
303:       this.pos.x = clamp(this.pos.x, -edge, edge);
304:       this.pos.z = clamp(this.pos.z, -edge, edge);
